{
  "name": "Gridiron AI: Dynasty Manager",
  "description": "A deep college football management simulation where you control recruiting, strategy, and game day decisions, powered by generative AI for realistic match simulations and storylines."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Position {
  QB = 'QB',
  RB = 'RB',
  WR = 'WR',
  OL = 'OL',
  DL = 'DL',
  LB = 'LB',
  DB = 'DB',
  K = 'K'
}

export enum PlayerYear {
  FR = 'FR',
  SO = 'SO',
  JR = 'JR',
  SR = 'SR'
}

export interface Player {
  id: string;
  name: string;
  position: Position;
  year: PlayerYear;
  rating: number; // 0-100
  hometown: string;
  stats: {
    games: number;
    yards: number;
    touchdowns: number;
  };
  potential: number; // Hidden stat for development
}

export interface Recruit extends Player {
  interest: number; // 0-100
  offers: string[]; // List of other teams offering
  committedTo: string | null;
  stars: number; // 1-5
}

export interface Team {
  id: string;
  name: string;
  abbreviation: string;
  color: string;
  prestige: number; // 0-100
  wins: number;
  losses: number;
  roster: Player[];
  strategy: {
    offense: 'Balanced' | 'Spread' | 'Pro-Style' | 'Option';
    defense: 'Balanced' | '4-3' | '3-4' | 'Blitz Heavy';
    aggression: number; // 1-10
  };
}

export interface GameStats {
  homeScore: number;
  awayScore: number;
  quarters: number[]; // Array of 4 numbers
  passingYards: number;
  rushingYards: number;
  turnovers: number;
  possessionTime: string;
}

export interface GameResult {
  week: number;
  opponentId: string;
  isHome: boolean;
  result: 'W' | 'L' | null;
  stats: GameStats | null;
  summary: string;
  playByPlayHighlights: string[];
}

export interface ScheduleItem {
  week: number;
  opponentId: string;
  isHome: boolean;
  played: boolean;
  result?: GameResult;
}

