import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Team, GameResult } from '../types';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

// Game Simulation Schema
const gameSimulationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    homeScore: { type: Type.INTEGER },
    awayScore: { type: Type.INTEGER },
    quarters: { 
      type: Type.ARRAY, 
      items: { type: Type.INTEGER },
      description: "Scores for Home team by quarter (just the home team score per quarter for simplicity logic in UI can deduce away)" 
    },
    summary: { type: Type.STRING, description: "A 3-sentence summary of the game narrative." },
    playByPlayHighlights: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "5 key moments from the game with timestamps (e.g., 'Q4 2:00 - TD pass...')"
    },
    stats: {
      type: Type.OBJECT,
      properties: {
        passingYards: { type: Type.INTEGER },
        rushingYards: { type: Type.INTEGER },
        turnovers: { type: Type.INTEGER },
        possessionTime: { type: Type.STRING }
      }
    }
  },
  required: ["homeScore", "awayScore", "summary", "playByPlayHighlights", "stats"]
};

export const simulateGameWithAI = async (
  homeTeam: Team, 
  awayTeam: Team
): Promise<GameResult | null> => {
  try {
    const prompt = `
      Simulate a college football game between:
      HOME: ${homeTeam.name} (OVR: ${homeTeam.prestige}, Offense: ${homeTeam.strategy.offense}, Aggression: ${homeTeam.strategy.aggression}/10)
      AWAY: ${awayTeam.name} (OVR: ${awayTeam.prestige}, Offense: ${awayTeam.strategy.offense})

      Based on the prestige difference and strategies, determine a realistic score and stats.
      If prestige is similar, it's a toss up. If one is much higher, they should likely win, but upsets happen.

      Return a JSON object with the final score, a brief summary, and key stats.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: gameSimulationSchema,
        temperature: 0.7
      }
    });

    const data = JSON.parse(response.text || '{}');

    // Fallback logic for quarters if API is weird
    const quarters = data.quarters && data.quarters.length === 4 ? data.quarters : [0,0,0,0];

    return {
      week: 0, // Set by caller
      opponentId: awayTeam.id,
      isHome: true,
      result: data.homeScore > data.awayScore ? 'W' : 'L',
      stats: {
        homeScore: data.homeScore,
        awayScore: data.awayScore,
        quarters: quarters,
        passingYards: data.stats.passingYards,
        rushingYards: data.stats.rushingYards,
        turnovers: data.stats.turnovers,
        possessionTime: data.stats.possessionTime
      },
      summary: data.summary,
      playByPlayHighlights: data.playByPlayHighlights
    };

  } catch (error) {
    console.error("Simulation failed:", error);
    // Fallback simulation
    return {
      week: 0,
      opponentId: awayTeam.id,
      isHome: true,
      result: 'W',
      stats: {
        homeScore: 21,
        awayScore: 17,
        quarters: [7, 0, 7, 7],
        passingYards: 200,
        rushingYards: 100,
        turnovers: 1,
        possessionTime: "30:00"
      },
      summary: "Simulation service unavailable. Default result generated.",
      playByPlayHighlights: ["Game played offline due to connection issues."]
    };
  }
};

const recruitSchema: Schema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      position: { type: Type.STRING },
      hometown: { type: Type.STRING },
      scoutingReport: { type: Type.STRING, description: "One sentence strength/weakness" },
      stars: { type: Type.INTEGER, description: "1 to 5 stars" }
    }
  }
};

export const generateRecruits = async (count: number): Promise<any[]> => {
  try {
    const prompt = `Generate ${count} realistic high school football recruits with names, positions, hometowns, star ratings (weighted towards 3 stars), and a brief scouting report.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: recruitSchema
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (e) {
    console.error(e);
    return [];
  }
};

import React from 'react';
import { Player, Position } from '../types';

interface PlayerCardProps {
  player: Player;
  compact?: boolean;
}

const getPositionColor = (pos: Position) => {
  switch (pos) {
    case Position.QB: return 'text-red-400 bg-red-400/10';
    case Position.RB:
    case Position.WR: return 'text-blue-400 bg-blue-400/10';
    case Position.OL: return 'text-orange-400 bg-orange-400/10';
    case Position.DL:
    case Position.LB: return 'text-purple-400 bg-purple-400/10';
    default: return 'text-emerald-400 bg-emerald-400/10';
  }
};

export const PlayerCard: React.FC<PlayerCardProps> = ({ player, compact = false }) => {
