import React from 'react';
import { Team } from '../types';

interface StrategyPanelProps {
  strategy: Team['strategy'];
  onUpdate: (newStrategy: Team['strategy']) => void;
}

export const StrategyPanel: React.FC<StrategyPanelProps> = ({ strategy, onUpdate }) => {
  return (
    <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
      <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
        Gameplan Strategy
      </h2>

      <div className="space-y-6">
        {/* Offense */}
        <div>
          <label className="block text-sm font-medium text-slate-400 mb-2">Offensive Scheme</label>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {['Balanced', 'Spread', 'Pro-Style', 'Option'].map((scheme) => (
              <button
                key={scheme}
                onClick={() => onUpdate({ ...strategy, offense: scheme as any })}
                className={`px-4 py-3 rounded-lg text-sm font-medium transition-all ${
                  strategy.offense === scheme
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/50 ring-1 ring-emerald-400'
                    : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                }`}
              >
                {scheme}
              </button>
            ))}
          </div>
        </div>

        {/* Defense */}
        <div>
          <label className="block text-sm font-medium text-slate-400 mb-2">Defensive Front</label>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {['Balanced', '4-3', '3-4', 'Blitz Heavy'].map((scheme) => (
              <button
                key={scheme}
                onClick={() => onUpdate({ ...strategy, defense: scheme as any })}
                className={`px-4 py-3 rounded-lg text-sm font-medium transition-all ${
                  strategy.defense === scheme
                    ? 'bg-red-600 text-white shadow-lg shadow-red-900/50 ring-1 ring-red-400'
                    : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                }`}
              >
                {scheme}
              </button>
            ))}
          </div>
        </div>

        {/* Aggression Slider */}
        <div>
          <div className="flex justify-between mb-2">
            <label className="block text-sm font-medium text-slate-400">Playcalling Aggression</label>
            <span className="text-emerald-400 font-bold">{strategy.aggression}/10</span>
          </div>
          <input
            type="range"
            min="1"
            max="10"
            value={strategy.aggression}
            onChange={(e) => onUpdate({ ...strategy, aggression: parseInt(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
          />
          <div className="flex justify-between text-xs text-slate-500 mt-1">
            <span>Conservative</span>
            <span>Risky</span>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { ICONS, INITIAL_USER_TEAM, OPPONENTS, generateRandomPlayer } from './constants';
import { Team, GameResult, Recruit, PlayerYear, Position } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateRecruits } from './services/geminiService';

const TABS = {
  DASHBOARD: 'Dashboard',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  SCHEDULE: 'Schedule'
};

const App = () => {
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [userTeam, setUserTeam] = useState<Team>(INITIAL_USER_TEAM);
  const [week, setWeek] = useState(1);
  const [gameHistory, setGameHistory] = useState<GameResult[]>([]);
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [loading, setLoading] = useState(false);
  const [simResult, setSimResult] = useState<GameResult | null>(null);

  // Initial Load of Recruits
  useEffect(() => {
    const fetchRecruits = async () => {
      const newRecruits = await generateRecruits(8);
      const formattedRecruits = newRecruits.map((r: any, idx: number) => ({
        ...generateRandomPlayer(`r-${idx}`, r.position as Position),
        name: r.name,
        hometown: r.hometown,
        stars: r.stars,
        interest: Math.floor(Math.random() * 40) + 10,
        offers: [],
        committedTo: null,
        scoutingReport: r.scoutingReport
      }));
      setRecruits(formattedRecruits);
    };
    fetchRecruits();
  }, []);

  const currentOpponent = OPPONENTS[(week - 1) % OPPONENTS.length];

  const handleSimulateGame = async () => {
    if (loading) return;
    setLoading(true);
    setSimResult(null);

    const result = await simulateGameWithAI(userTeam, currentOpponent);

    if (result) {
      result.week = week;
      setSimResult(result);
      setGameHistory([result, ...gameHistory]);

      // Update Wins/Losses
      const isWin = result.result === 'W';
      setUserTeam(prev => ({
        ...prev,
        wins: isWin ? prev.wins + 1 : prev.wins,
        losses: isWin ? prev.losses : prev.losses + 1
      }));
    }
    setLoading(false);
  };

  const advanceWeek = () => {
    setWeek(w => w + 1);
    setSimResult(null);
  };

  const handleRecruitAction = (recruitId: string) => {
    setRecruits(prev => prev.map(r => {
      if (r.id === recruitId && !r.committedTo) {
        // Simple logic: boost interest, chance to commit
        const newInterest = Math.min(100, r.interest + 15);
        const committed = newInterest > 90 && Math.random() > 0.5 ? userTeam.id : null;
        return { ...r, interest: newInterest, committedTo: committed };
      }
      return r;
    }));
  };

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      {/* Status Bar */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-emerald-500/10 rounded-lg text-emerald-400">
            <ICONS.Trophy />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Record</div>
            <div className="text-2xl font-black text-white">{userTeam.wins} - {userTeam.losses}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400">
            <ICONS.Calendar />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Current Week</div>
            <div className="text-2xl font-black text-white">Week {week}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-purple-500/10 rounded-lg text-purple-400">
            <ICONS.Clipboard />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Team Prestige</div>
            <div className="text-2xl font-black text-white">{userTeam.prestige} <span className="text-sm text-slate-500 font-normal">/ 100</span></div>
          </div>
        </div>
      </div>

      {/* Main Action Area: Next Game or Result */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Next Matchup Card */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-xl border border-slate-700 overflow-hidden relative">
           <div className="p-6 border-b border-slate-700/50 flex justify-between items-center">
