import React, { useState, useEffect, useCallback } from 'react';
import { ICONS, INITIAL_USER_TEAM, OPPONENTS, generateRandomPlayer } from './constants';
import { Team, GameResult, Recruit, PlayerYear, Position } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateRecruits } from './services/geminiService';

const TABS = {
  DASHBOARD: 'Dashboard',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  SCHEDULE: 'Schedule'
};

const ROSTER_FILTERS = {
  ALL: 'All',
  OFFENSE: 'Offense',
  DEFENSE: 'Defense',
  SPECIAL: 'Special'
};

const POSITIONS = {
  [ROSTER_FILTERS.OFFENSE]: [Position.QB, Position.RB, Position.WR, Position.OL],
  [ROSTER_FILTERS.DEFENSE]: [Position.DL, Position.LB, Position.DB],
  [ROSTER_FILTERS.SPECIAL]: [Position.K]
};

const App = () => {
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [userTeam, setUserTeam] = useState<Team>(INITIAL_USER_TEAM);
  const [week, setWeek] = useState(1);
  const [gameHistory, setGameHistory] = useState<GameResult[]>([]);
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [loading, setLoading] = useState(false);
  const [simResult, setSimResult] = useState<GameResult | null>(null);

  // Recruiting State
  const [scholarshipsAvailable, setScholarshipsAvailable] = useState(25);

  // Roster State
  const [rosterFilter, setRosterFilter] = useState(ROSTER_FILTERS.ALL);

  // Initial Load of Recruits
  useEffect(() => {
    const fetchRecruits = async () => {
      // Increased from 8 to 35 to give more variety for the 25 spots
      const newRecruits = await generateRecruits(35);
      const formattedRecruits = newRecruits.map((r: any, idx: number) => ({
        ...generateRandomPlayer(`r-${idx}`, r.position as Position),
        name: r.name,
        hometown: r.hometown,
        stars: r.stars,
        interest: Math.floor(Math.random() * 40) + 10,
        offers: [],
        committedTo: null,
        scoutingReport: r.scoutingReport
      }));
      setRecruits(formattedRecruits);
    };
    fetchRecruits();
  }, []);

  const currentOpponent = OPPONENTS[(week - 1) % OPPONENTS.length];

  const handleSimulateGame = async () => {
    if (loading) return;
    setLoading(true);
    setSimResult(null);

    const result = await simulateGameWithAI(userTeam, currentOpponent);

    if (result) {
      result.week = week;
      setSimResult(result);
      setGameHistory([result, ...gameHistory]);

      // Update Wins/Losses
      const isWin = result.result === 'W';
      setUserTeam(prev => ({
        ...prev,
        wins: isWin ? prev.wins + 1 : prev.wins,
        losses: isWin ? prev.losses : prev.losses + 1
      }));
    }
    setLoading(false);
  };

  const advanceWeek = () => {
    setWeek(w => w + 1);
    setSimResult(null);
  };

  const handleRecruitAction = (recruitId: string) => {
    if (scholarshipsAvailable <= 0) return;

    setRecruits(prev => prev.map(r => {
      if (r.id === recruitId && !r.committedTo) {
        // Boost interest
        const newInterest = Math.min(100, r.interest + 15);

        // Commitment logic: Must have high interest and a random chance
        // If interest is very high (90+), ~40% chance to commit immediately on pitch
        // In a real game this would be more complex (visit, offer, etc)
        let isCommitted = false;

        if (newInterest >= 95 && Math.random() > 0.4) {
           isCommitted = true;
        } else if (newInterest >= 80 && Math.random() > 0.7) {
           isCommitted = true;
        }

        if (isCommitted) {
           setScholarshipsAvailable(s => s - 1);
           return { ...r, interest: newInterest, committedTo: userTeam.id };
        }

        return { ...r, interest: newInterest };
      }
      return r;
    }));
  };

  const getFilteredRoster = () => {
    if (rosterFilter === ROSTER_FILTERS.ALL) return userTeam.roster;

    const allowedPositions = POSITIONS[rosterFilter as keyof typeof POSITIONS];
    return userTeam.roster.filter(p => allowedPositions.includes(p.position));
  };

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      {/* Status Bar */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-emerald-500/10 rounded-lg text-emerald-400">
            <ICONS.Trophy />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Record</div>
            <div className="text-2xl font-black text-white">{userTeam.wins} - {userTeam.losses}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400">
            <ICONS.Calendar />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Current Week</div>
            <div className="text-2xl font-black text-white">Week {week}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-purple-500/10 rounded-lg text-purple-400">
            <ICONS.Clipboard />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Team Prestige</div>
            <div className="text-2xl font-black text-white">{userTeam.prestige} <span className="text-sm text-slate-500 font-normal">/ 100</span></div>
          </div>
        </div>
      </div>

      {/* Main Action Area: Next Game or Result */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Next Matchup Card */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-xl border border-slate-700 overflow-hidden relative">
           <div className="p-6 border-b border-slate-700/50 flex justify-between items-center">
              <h2 className="text-lg font-bold text-white flex items-center gap-2">
                 <ICONS.Football className="w-5 h-5 text-emerald-400"/> Game Day
              </h2>
              {simResult && <span className="text-xs bg-slate-700 text-slate-300 px-2 py-1 rounded">Final</span>}
           </div>

           <div className="p-8">
             {!simResult ? (
               <div className="text-center">
                 <div className="flex justify-center items-center gap-8 mb-8">
                   <div className="text-center">
                     <div className={`w-16 h-16 ${userTeam.color} rounded-full flex items-center justify-center text-xl font-black text-white shadow-lg mx-auto mb-3`}>
                       {userTeam.abbreviation}
                     </div>
                     <div className="font-bold text-white">{userTeam.name}</div>
                     <div className="text-sm text-slate-400">({userTeam.wins}-{userTeam.losses})</div>
                   </div>
                   <div className="text-2xl font-black text-slate-600">VS</div>
                   <div className="text-center">
                     <div className={`w-16 h-16 ${currentOpponent.color} rounded-full flex items-center justify-center text-xl font-black text-white shadow-lg mx-auto mb-3`}>
                       {currentOpponent.abbreviation}
                     </div>
                     <div className="font-bold text-white">{currentOpponent.name}</div>
                     <div className="text-sm text-slate-400">({currentOpponent.wins}-{currentOpponent.losses})</div>
                   </div>
                 </div>

                 <button 
                   onClick={handleSimulateGame}
                   disabled={loading}
                   className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white font-bold rounded-lg shadow-lg shadow-emerald-900/50 transition-all flex items-center justify-center gap-2"
                 >
                   {loading ? (
                     <>
                       <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"/>
                       Simulating...
                     </>
                   ) : (
                     <>
                       <ICONS.Play className="w-5 h-5"/> Simulate Game
                     </>
                   )}
                 </button>
               </div>
             ) : (
               <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                 <div className="flex justify-between items-center mb-6">
                    <div className="text-center">
                      <div className="text-4xl font-black text-white mb-1">{simResult.stats?.homeScore}</div>
                      <div className="text-emerald-400 font-bold">{userTeam.abbreviation}</div>
                    </div>
                    <div className="text-slate-500 text-sm font-medium uppercase tracking-widest">Final</div>
                    <div className="text-center">
                      <div className="text-4xl font-black text-white mb-1">{simResult.stats?.awayScore}</div>
                      <div className="text-slate-400 font-bold">{currentOpponent.abbreviation}</div>
                    </div>
                 </div>

                 <div className="bg-slate-950/50 rounded-lg p-4 mb-6 text-sm text-slate-300 leading-relaxed border border-slate-800">
                   {simResult.summary}
                 </div>

                 <div className="space-y-2 mb-6">
                   {simResult.playByPlayHighlights.map((highlight, i) => (
                     <div key={i} className="flex gap-3 text-xs text-slate-400 border-b border-slate-800 pb-2 last:border-0">
                       <span className="text-emerald-500 font-bold min-w-[20px]">•</span>
                       {highlight}
                     </div>
                   ))}
                 </div>

                 <button 
                   onClick={advanceWeek}
                   className="w-full py-3 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-lg transition-colors"
                 >
                   Advance Week
                 </button>
               </div>
             )}
           </div>
        </div>

        {/* Quick Stats / News */}
        <div className="space-y-6">
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
             <h3 className="text-slate-200 font-bold mb-4">Season Leaders</h3>
             <div className="space-y-4">
               {userTeam.roster.slice(0, 3).map((p, i) => (
                 <div key={p.id} className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-300">{i+1}</div>
                      <div>
                        <div className="text-sm font-bold text-white">{p.name}</div>
                        <div className="text-xs text-slate-500">{p.position}</div>
                      </div>
                    </div>
                    <div className="text-sm font-mono text-emerald-400">{p.rating} OVR</div>
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderRoster = () => (
    <div className="space-y-4 animate-fade-in">
       {/* Roster Filter Bar */}
       <div className="flex items-center gap-2 overflow-x-auto pb-2">
         <div className="text-slate-400 mr-2">
           <ICONS.Filter className="w-5 h-5"/>
         </div>
         {Object.values(ROSTER_FILTERS).map(filter => (
           <button
             key={filter}
             onClick={() => setRosterFilter(filter)}
             className={`px-4 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-all ${
               rosterFilter === filter 
                 ? 'bg-emerald-600 text-white' 
                 : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'
             }`}
           >
             {filter}
           </button>
         ))}
         <div className="ml-auto text-sm text-slate-500">
            {getFilteredRoster().length} Players
         </div>
       </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {getFilteredRoster().sort((a,b) => b.rating - a.rating).map((player) => (
          <PlayerCard key={player.id} player={player} />
        ))}
      </div>
    </div>
  );

  const renderRecruiting = () => (
    <div className="space-y-4 animate-fade-in">
      <div className="flex justify-between items-center mb-4 bg-slate-800 p-4 rounded-xl border border-slate-700">
        <div>
           <h2 className="text-xl font-bold text-white">Top Targets</h2>
           <p className="text-xs text-slate-400">Class of 2025</p>
        </div>
        <div className="text-right">
          <div className={`text-2xl font-black ${scholarshipsAvailable > 0 ? 'text-emerald-400' : 'text-red-400'}`}>
            {scholarshipsAvailable}
          </div>
          <div className="text-xs text-slate-400 uppercase font-bold tracking-wide">Scholarships Left</div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {recruits.length === 0 ? (
          <div className="text-center p-12 text-slate-500">
             <div className="animate-pulse mb-2">Scouting nationwide talent...</div>
             <div className="text-xs">Generating ~35 recruits</div>
          </div>
        ) : (
          recruits.map((recruit) => (
            <div key={recruit.id} className="bg-slate-800 p-4 rounded-xl border border-slate-700 flex flex-col md:flex-row items-center justify-between gap-4 group hover:border-slate-600 transition-colors">
               <div className="flex-1">
                 <div className="flex items-center gap-2 mb-1">
                   {Array.from({length: recruit.stars}).map((_, i) => (
                     <svg key={i} className="w-4 h-4 text-yellow-500 fill-current" viewBox="0 0 24 24"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
                   ))}
                   <span className="text-xs text-slate-500 font-bold ml-1">{recruit.stars} STAR</span>
                 </div>
                 <h3 className="font-bold text-lg text-white group-hover:text-emerald-400 transition-colors">{recruit.name}</h3>
                 <p className="text-sm text-slate-400 flex items-center gap-2">
                   <span className="font-mono text-slate-300">{recruit.position}</span> 
                   <span className="w-1 h-1 bg-slate-600 rounded-full"></span>
                   {recruit.hometown}
                 </p>
                 <p className="text-xs text-slate-500 mt-2 italic">"{recruit.scoutingReport}"</p>
               </div>

               <div className="w-full md:w-48">
                 <div className="flex justify-between text-xs text-slate-400 mb-1">
                   <span>Interest</span>
                   <span>{recruit.interest}%</span>
                 </div>
                 <div className="w-full bg-slate-700 rounded-full h-2 mb-3">
                   <div 
                     className={`h-2 rounded-full transition-all duration-500 ${recruit.interest > 70 ? 'bg-emerald-500' : recruit.interest > 40 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                     style={{width: `${recruit.interest}%`}}
                   ></div>
                 </div>

                 {recruit.committedTo === userTeam.id ? (
                    <div className="w-full py-2 bg-emerald-500/20 text-emerald-400 text-center text-sm font-bold rounded border border-emerald-500/50">
                       SIGNED
                    </div>
                 ) : recruit.committedTo ? (
                    <div className="w-full py-2 bg-slate-700/50 text-slate-500 text-center text-sm font-bold rounded border border-slate-700">
                       LOCKED
                    </div>
                 ) : (
                    <button 
                      onClick={() => handleRecruitAction(recruit.id)}
                      disabled={scholarshipsAvailable === 0}
                      className="w-full py-2 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-700 disabled:text-slate-500 disabled:cursor-not-allowed text-white text-sm font-bold rounded transition-colors"
                    >
                      {scholarshipsAvailable > 0 ? 'Offer & Pitch' : 'No Spots'}
                    </button>
                 )}
               </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 font-sans selection:bg-emerald-500/30">

      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-md bg-opacity-80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-emerald-600 rounded flex items-center justify-center">
                 <ICONS.Football className="text-white w-5 h-5" />
              </div>
              <span className="font-black text-xl tracking-tight text-white hidden sm:block">GRIDIRON<span className="text-emerald-500">AI</span></span>
            </div>

            <nav className="flex gap-1 md:gap-4 overflow-x-auto">
              {[TABS.DASHBOARD, TABS.ROSTER, TABS.RECRUITING, TABS.STRATEGY].map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-3 py-2 text-sm font-medium rounded-md transition-colors whitespace-nowrap ${
                    activeTab === tab 
                    ? 'bg-slate-800 text-emerald-400' 
                    : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
                  }`}
                >
                  {tab}
                </button>
              ))}
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === TABS.DASHBOARD && renderDashboard()}
        {activeTab === TABS.ROSTER && renderRoster()}
        {activeTab === TABS.RECRUITING && renderRecruiting()}
        {activeTab === TABS.STRATEGY && (
          <div className="animate-fade-in">
             <StrategyPanel 
                strategy={userTeam.strategy} 
                onUpdate={(s) => setUserTeam({...userTeam, strategy: s})} 
             />
          </div>
        )}
      </main>

    </div>
  );
};

export default App;

export enum Position {
  QB = 'QB',
  RB = 'RB',
  WR = 'WR',
  OL = 'OL',
  DL = 'DL',
  LB = 'LB',
  DB = 'DB',
  K = 'K'
}

export enum PlayerYear {
  FR = 'FR',
  SO = 'SO',
  JR = 'JR',
  SR = 'SR'
}

export interface Player {
  id: string;
  name: string;
  position: Position;
  year: PlayerYear;
  rating: number; // 0-100
  hometown: string;
  stats: {
    games: number;
    yards: number;
    touchdowns: number;
  };
  potential: number; // Hidden stat for development
}

export interface Recruit extends Player {
  interest: number; // 0-100
  offers: string[]; // List of other teams offering
  committedTo: string | null;
  stars: number; // 1-5
  scoutingReport?: string;
}

export interface Team {
  id: string;
  name: string;
  abbreviation: string;
  color: string;
  prestige: number; // 0-100
  wins: number;
  losses: number;
  roster: Player[];
  strategy: {
    offense: 'Balanced' | 'Spread' | 'Pro-Style' | 'Option';
    defense: 'Balanced' | '4-3' | '3-4' | 'Blitz Heavy';
    aggression: number; // 1-10
  };
}

export interface GameStats {
  homeScore: number;
  awayScore: number;
  quarters: number[]; // Array of 4 numbers
  passingYards: number;
  rushingYards: number;
  turnovers: number;
  possessionTime: string;
}

export interface GameResult {
  week: number;
  opponentId: string;
  isHome: boolean;
  result: 'W' | 'L' | null;
  stats: GameStats | null;
  summary: string;
  playByPlayHighlights: string[];
}

export interface ScheduleItem {
  week: number;
  opponentId: string;
  isHome: boolean;
  played: boolean;
  result?: GameResult;
}

import React, { useState, useEffect } from 'react';
import { ICONS, INITIAL_USER_TEAM, OPPONENTS, generateRandomPlayer } from './constants';
import { Team, GameResult, Recruit, Position } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateRecruits } from './services/geminiService';

const TABS = {
  DASHBOARD: 'Dashboard',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  SCHEDULE: 'Schedule'
};

// Filter Definitions
const OFFENSE_POSITIONS = [Position.QB, Position.RB, Position.WR, Position.OL];
const DEFENSE_POSITIONS = [Position.DL, Position.LB, Position.DB];

const FILTER_ITEMS = [
  'All',
  'Offense',
  'Defense',
  ...Object.values(Position)
];

const getFilteredItems = (items: any[], filter: string) => {
  if (filter === 'All') return items;
  if (filter === 'Offense') return items.filter(i => OFFENSE_POSITIONS.includes(i.position));
  if (filter === 'Defense') return items.filter(i => DEFENSE_POSITIONS.includes(i.position));
  return items.filter(i => i.position === filter);
};

const App = () => {
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [userTeam, setUserTeam] = useState<Team>(INITIAL_USER_TEAM);
  const [week, setWeek] = useState(1);
  const [gameHistory, setGameHistory] = useState<GameResult[]>([]);
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [loading, setLoading] = useState(false);
  const [simResult, setSimResult] = useState<GameResult | null>(null);

  // Recruiting State
  const [scholarshipsAvailable, setScholarshipsAvailable] = useState(25);

  // Filter States
  const [rosterFilter, setRosterFilter] = useState('All');
  const [recruitingFilter, setRecruitingFilter] = useState('All');

  // Initial Load of Recruits
  useEffect(() => {
    const fetchRecruits = async () => {
      // Increased from 8 to 35 to give more variety for the 25 spots
      const newRecruits = await generateRecruits(35);
      const formattedRecruits = newRecruits.map((r: any, idx: number) => ({
        ...generateRandomPlayer(`r-${idx}`, r.position as Position),
        name: r.name,
        hometown: r.hometown,
        stars: r.stars,
        interest: Math.floor(Math.random() * 40) + 10,
        offers: [],
        committedTo: null,
        scoutingReport: r.scoutingReport
      }));
      setRecruits(formattedRecruits);
    };
    fetchRecruits();
  }, []);

  const currentOpponent = OPPONENTS[(week - 1) % OPPONENTS.length];

  const handleSimulateGame = async () => {
    if (loading) return;
    setLoading(true);
    setSimResult(null);

    const result = await simulateGameWithAI(userTeam, currentOpponent);

    if (result) {
      result.week = week;
      setSimResult(result);
      setGameHistory([result, ...gameHistory]);

      // Update Wins/Losses
      const isWin = result.result === 'W';
      setUserTeam(prev => ({
        ...prev,
        wins: isWin ? prev.wins + 1 : prev.wins,
        losses: isWin ? prev.losses : prev.losses + 1
      }));
    }
    setLoading(false);
  };

  const advanceWeek = () => {
    setWeek(w => w + 1);
    setSimResult(null);
  };

  const handleRecruitAction = (recruitId: string) => {
    if (scholarshipsAvailable <= 0) return;

    setRecruits(prev => prev.map(r => {
      if (r.id === recruitId && !r.committedTo) {
        // Boost interest
        const newInterest = Math.min(100, r.interest + 15);

        // Commitment logic: Must have high interest and a random chance
        // If interest is very high (90+), ~40% chance to commit immediately on pitch
        // In a real game this would be more complex (visit, offer, etc)
        let isCommitted = false;

        if (newInterest >= 95 && Math.random() > 0.4) {
           isCommitted = true;
        } else if (newInterest >= 80 && Math.random() > 0.7) {
           isCommitted = true;
        }

        if (isCommitted) {
           setScholarshipsAvailable(s => s - 1);
           return { ...r, interest: newInterest, committedTo: userTeam.id };
        }

        return { ...r, interest: newInterest };
      }
      return r;
    }));
  };

  const renderFilterBar = (currentFilter: string, setFilter: (f: string) => void, items: any[]) => (
    <div className="flex items-center gap-2 overflow-x-auto pb-4 no-scrollbar">
       <div className="text-slate-400 mr-2 shrink-0">
         <ICONS.Filter className="w-5 h-5"/>
       </div>
       {FILTER_ITEMS.map(filter => {
         const count = getFilteredItems(items, filter).length;
         const isActive = currentFilter === filter;

         return (
           <button
             key={filter}
             onClick={() => setFilter(filter)}
             className={`px-3 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all flex items-center gap-2 border ${
               isActive 
                 ? 'bg-emerald-600 border-emerald-500 text-white shadow-lg shadow-emerald-900/20' 
                 : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500 hover:text-white'
             }`}
           >
             {filter}
             <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${
               isActive ? 'bg-black/20 text-white' : 'bg-slate-700 text-slate-500'
             }`}>
               {count}
             </span>
           </button>
         );
       })}
    </div>
  );

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      {/* Status Bar */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-emerald-500/10 rounded-lg text-emerald-400">
            <ICONS.Trophy />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Record</div>
            <div className="text-2xl font-black text-white">{userTeam.wins} - {userTeam.losses}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400">
            <ICONS.Calendar />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Current Week</div>
            <div className="text-2xl font-black text-white">Week {week}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-purple-500/10 rounded-lg text-purple-400">
            <ICONS.Clipboard />
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Team Prestige</div>
            <div className="text-2xl font-black text-white">{userTeam.prestige} <span className="text-sm text-slate-500 font-normal">/ 100</span></div>
          </div>
        </div>
      </div>

      {/* Main Action Area: Next Game or Result */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Next Matchup Card */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-xl border border-slate-700 overflow-hidden relative">
           <div className="p-6 border-b border-slate-700/50 flex justify-between items-center">
              <h2 className="text-lg font-bold text-white flex items-center gap-2">
                 <ICONS.Football className="w-5 h-5 text-emerald-400"/> Game Day
              </h2>
              {simResult && <span className="text-xs bg-slate-700 text-slate-300 px-2 py-1 rounded">Final</span>}
           </div>

           <div className="p-8">
             {!simResult ? (
               <div className="text-center">
                 <div className="flex justify-center items-center gap-8 mb-8">
                   <div className="text-center">
                     <div className={`w-16 h-16 ${userTeam.color} rounded-full flex items-center justify-center text-xl font-black text-white shadow-lg mx-auto mb-3`}>
                       {userTeam.abbreviation}
                     </div>
                     <div className="font-bold text-white">{userTeam.name}</div>
                     <div className="text-sm text-slate-400">({userTeam.wins}-{userTeam.losses})</div>
                   </div>
                   <div className="text-2xl font-black text-slate-600">VS</div>
                   <div className="text-center">
                     <div className={`w-16 h-16 ${currentOpponent.color} rounded-full flex items-center justify-center text-xl font-black text-white shadow-lg mx-auto mb-3`}>
                       {currentOpponent.abbreviation}
                     </div>
                     <div className="font-bold text-white">{currentOpponent.name}</div>
                     <div className="text-sm text-slate-400">({currentOpponent.wins}-{currentOpponent.losses})</div>
                   </div>
                 </div>

                 <button 
                   onClick={handleSimulateGame}
                   disabled={loading}
                   className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white font-bold rounded-lg shadow-lg shadow-emerald-900/50 transition-all flex items-center justify-center gap-2"
                 >
                   {loading ? (
                     <>
                       <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"/>
                       Simulating...
                     </>
                   ) : (
                     <>
                       <ICONS.Play className="w-5 h-5"/> Simulate Game
                     </>
                   )}
                 </button>
               </div>
             ) : (
               <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                 <div className="flex justify-between items-center mb-6">
                    <div className="text-center">
                      <div className="text-4xl font-black text-white mb-1">{simResult.stats?.homeScore}</div>
                      <div className="text-emerald-400 font-bold">{userTeam.abbreviation}</div>
                    </div>
                    <div className="text-slate-500 text-sm font-medium uppercase tracking-widest">Final</div>
                    <div className="text-center">
