const firstNames = ["James", "John", "Robert", "Michael", "William", "David", "Richard", "Joseph", "Thomas", "Charles", "Deion", "Tyreek", "Peyton", "Arch", "Bo", "Herschel", "Travis", "Shedeur", "Quinn"];
const lastNames = ["Smith", "Johnson", "Williams", "Brown", "Jones", "Garcia", "Miller", "Davis", "Rodriguez", "Martinez", "Sanders", "Manning", "Nix", "Jackson", "Hunter", "Ewers", "Beck"];
const hometowns = ["Atlanta, GA", "Houston, TX", "Miami, FL", "Dallas, TX", "Los Angeles, CA", "Chicago, IL", "Birmingham, AL", "Columbus, OH", "Bradenton, FL", "Austin, TX"];

export const generateRandomPlayer = (id: string, fixedPos?: Position, minRating = 60, maxRating = 99): any => {
  const posKeys = Object.keys(Position);
  const position = fixedPos || Position[posKeys[Math.floor(Math.random() * posKeys.length)] as keyof typeof Position];

  const yearKeys = Object.keys(PlayerYear);
  const year = PlayerYear[yearKeys[Math.floor(Math.random() * yearKeys.length)] as keyof typeof PlayerYear];

  // Adjust rating based on year slightly (Seniors usually better than Freshmen)
  const yearBonus = year === PlayerYear.SR ? 5 : year === PlayerYear.JR ? 3 : year === PlayerYear.SO ? 1 : 0;
  const actualRating = Math.min(99, Math.floor(Math.random() * (maxRating - minRating + 1)) + minRating + yearBonus);

  return {
    id,
    name: `${firstNames[Math.floor(Math.random() * firstNames.length)]} ${lastNames[Math.floor(Math.random() * lastNames.length)]}`,
    position,
    year,
    rating: actualRating,
    hometown: hometowns[Math.floor(Math.random() * hometowns.length)],
    stats: { games: 0, yards: 0, touchdowns: 0 },
    potential: Math.floor(Math.random() * 20) + 80
  };
};

const generateBalancedRoster = (teamId: string) => {
  const distribution = {
    [Position.QB]: 4,
    [Position.RB]: 6,
    [Position.WR]: 9,
    [Position.OL]: 14,
    [Position.DL]: 10,
    [Position.LB]: 9,
    [Position.DB]: 12,
    [Position.K]: 3
  };

  let roster: any[] = [];
  let idCounter = 0;

  Object.entries(distribution).forEach(([pos, count]) => {
    for (let i = 0; i < count; i++) {
      // Create a mix of ratings: Starters (better), Depth (worse)
      // Top 30% are 'starters' material
      const isStarter = i < Math.ceil(count * 0.3);
      const min = isStarter ? 82 : 68;
      const max = isStarter ? 95 : 79;
      roster.push(generateRandomPlayer(`${teamId}-p-${idCounter++}`, pos as Position, min, max));
    }
  });

  return roster;
};

