import React, { useState, useEffect } from 'react';
import { ICONS, INITIAL_USER_TEAM, OPPONENTS, generateRandomPlayer } from './constants';
import { Team, GameResult, Recruit, Position } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateRecruits } from './services/geminiService';

const TABS = {
  DASHBOARD: 'Dashboard',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  SCHEDULE: 'Schedule'
};

// Filter Definitions
const OFFENSE_POSITIONS = [Position.QB, Position.RB, Position.WR, Position.OL];
const DEFENSE_POSITIONS = [Position.DL, Position.LB, Position.DB];

const FILTER_ITEMS = [
  'All',
  'Offense',
  'Defense',
  ...Object.values(Position)
];

const WEEKLY_RECRUITING_POINTS = 100;

const COSTS = {
  SCOUT: 10,
  CALL: 5,
  VISIT: 25,
  OFFER: 0
};

const getFilteredItems = (items: any[], filter: string) => {
  if (filter === 'All') return items;
  if (filter === 'Offense') return items.filter(i => OFFENSE_POSITIONS.includes(i.position));
  if (filter === 'Defense') return items.filter(i => DEFENSE_POSITIONS.includes(i.position));
  return items.filter(i => i.position === filter);
};

const App = () => {
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [userTeam, setUserTeam] = useState<Team>(INITIAL_USER_TEAM);
  const [week, setWeek] = useState(1);
  const [gameHistory, setGameHistory] = useState<GameResult[]>([]);
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [loading, setLoading] = useState(false);
  const [simResult, setSimResult] = useState<GameResult | null>(null);

  // Recruiting State
  const [scholarshipsAvailable, setScholarshipsAvailable] = useState(25);
  const [recruitingPoints, setRecruitingPoints] = useState(WEEKLY_RECRUITING_POINTS);

  // Filter States
  const [rosterFilter, setRosterFilter] = useState('All');
  const [recruitingFilter, setRecruitingFilter] = useState('All');

  // Initial Load of Recruits
  useEffect(() => {
    const fetchRecruits = async () => {
      // Increased from 8 to 35 to give more variety for the 25 spots
      const newRecruits = await generateRecruits(35);
      const formattedRecruits = newRecruits.map((r: any, idx: number) => ({
        ...generateRandomPlayer(`r-${idx}`, r.position as Position),
        name: r.name,
        hometown: r.hometown,
        stars: r.stars,
        interest: Math.floor(Math.random() * 40) + 10,
        offers: [],
        committedTo: null,
        scoutingReport: r.scoutingReport,
        isScouted: false,
        isOffered: false
      }));
      setRecruits(formattedRecruits);
    };
    fetchRecruits();
  }, []);

  const currentOpponent = OPPONENTS[(week - 1) % OPPONENTS.length];

  const handleSimulateGame = async () => {
    if (loading) return;
    setLoading(true);
    setSimResult(null);

    const result = await simulateGameWithAI(userTeam, currentOpponent);

    if (result) {
      result.week = week;
      setSimResult(result);
      setGameHistory([result, ...gameHistory]);

      // Update Wins/Losses
      const isWin = result.result === 'W';
      setUserTeam(prev => ({
        ...prev,
        wins: isWin ? prev.wins + 1 : prev.wins,
        losses: isWin ? prev.losses : prev.losses + 1
      }));
    }
    setLoading(false);
  };

  const advanceWeek = () => {
    // Reset Recruiting Points
    setRecruitingPoints(WEEKLY_RECRUITING_POINTS);

    // Process Recruiting Sim (Other teams acting, random variance)
    setRecruits(prev => prev.map(r => {
      if (r.committedTo) return r;

      // Randomly decrease interest if no interaction (simulating decay or other teams)
      const decay = Math.random() > 0.6 ? Math.floor(Math.random() * 3) + 1 : 0;
      let newInterest = Math.max(0, r.interest - decay);

      // Random chance for other teams to lock/steal if interest is low
      let committedTo = r.committedTo;
      if (!committedTo && newInterest < 40 && Math.random() < 0.05) {
         committedTo = 'opp-tech'; // Generic cpu steal
      }

      // Check for user commitment if offered and interest is high
      if (!committedTo && r.isOffered && r.interest >= 90 && scholarshipsAvailable > 0) {
         // Chance to commit increases with interest
         const commitChance = (r.interest - 80) / 100; // e.g. 95 interest = 15% chance per week
         if (Math.random() < commitChance) {
            committedTo = userTeam.id;
            setScholarshipsAvailable(s => Math.max(0, s - 1));
         }
      }

      return { ...r, interest: newInterest, committedTo };
    }));

    setWeek(w => w + 1);
    setSimResult(null);
  };

  const handleRecruitAction = (action: 'SCOUT' | 'CALL' | 'VISIT' | 'OFFER', recruitId: string) => {
    const cost = COSTS[action];

    if (recruitingPoints < cost) return;
    if (action === 'OFFER' && scholarshipsAvailable <= 0) return;

    // Deduct points (except OFFER is 0 cost but limited by scholarships elsewhere/logic)
    if (cost > 0) setRecruitingPoints(p => p - cost);

    setRecruits(prev => prev.map(r => {
      if (r.id !== recruitId) return r;
      if (r.committedTo) return r;

      let updates: Partial<Recruit> = {};
      let interestBoost = 0;

      switch(action) {
        case 'SCOUT':
          updates.isScouted = true;
          interestBoost = 2;
          break;
        case 'CALL':
          interestBoost = Math.floor(Math.random() * 4) + 2;
          break;
        case 'VISIT':
          interestBoost = Math.floor(Math.random() * 10) + 10;
          break;
        case 'OFFER':
          if (!r.isOffered) {
            updates.isOffered = true;
            interestBoost = 15;
          }
          break;
      }

      // Diminishing returns if interest is already high
      if (r.interest > 90) interestBoost = Math.ceil(interestBoost * 0.5);

      return { 
        ...r, 
        ...updates,
        interest: Math.min(100, r.interest + interestBoost) 
      };
    }));
  };

