                                    onClick={() => handleRecruitAction('VISIT', recruit.id)}
                                    disabled={recruitingPoints < COSTS.VISIT}
                                    className="py-2 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 text-white text-xs font-bold rounded"
