                 </div>
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 font-sans selection:bg-emerald-500/30">

      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-md bg-opacity-80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-emerald-600 rounded flex items-center justify-center">
                 <ICONS.Football className="text-white w-5 h-5" />
              </div>
              <span className="font-black text-xl tracking-tight text-white hidden sm:block">GRIDIRON<span className="text-emerald-500">AI</span></span>
            </div>

            <nav className="flex gap-1 md:gap-4 overflow-x-auto">
              {[TABS.DASHBOARD, TABS.ROSTER, TABS.RECRUITING, TABS.STRATEGY].map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-3 py-2 text-sm font-medium rounded-md transition-colors whitespace-nowrap ${
