  if (!userTeam) return null;

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className={`p-3 rounded-lg text-white shadow-lg ${userTeam.color}`}>
            <div className="font-bold text-xl">{userTeam.abbreviation}</div>
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Record</div>
            <div className="text-2xl font-black text-white">{userTeam.stats.wins} - {userTeam.stats.losses}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
