                               <span className={m.winnerId === h?.id ? 'text-emerald-400 font-bold' : 'text-slate-300'}>{h?.name}</span>
                               <span className="text-slate-500">vs</span>
                               <span className={m.winnerId === a?.id ? 'text-emerald-400 font-bold' : 'text-slate-300'}>{a?.name}</span>
                            </div>
