                 <ICONS.Football className="text-white w-5 h-5" />
              </div>
              <span className="font-black text-xl tracking-tight text-white hidden sm:block">GRIDIRON<span className="text-emerald-500">AI</span></span>
            </div>
            {viewState === 'DYNASTY_HUB' && (
              <nav className="flex gap-1 md:gap-4 overflow-x-auto">
                {Object.values(TABS).map((tab) => (
                  <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-3 py-2 text-sm font-medium rounded-md transition-colors whitespace-nowrap ${
                      activeTab === tab 
                      ? 'bg-slate-800 text-emerald-400' 
                      : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
                    }`}
                  >
                    {tab}
                  </button>
                ))}
              </nav>
            )}
            {viewState !== 'DYNASTY_HUB' && (
               <div className="text-sm font-bold text-slate-500 uppercase tracking-widest">{viewState === 'CREATE_COACH' ? 'New Career' : 'Contract Offer'}</div>
            )}
          </div>
        </div>
      </header>
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === TABS.DASHBOARD && renderDashboard()}
        {activeTab === TABS.STANDINGS && renderStandings()}
        {activeTab === TABS.ROSTER && (
           <div className="space-y-4">
              <div className="flex items-center gap-2 overflow-x-auto pb-4">{/* Filters */}</div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {getFilteredItems(userTeam.roster, rosterFilter).sort((a:any,b:any) => b.rating - a.rating).map((p: any) => <PlayerCard key={p.id} player={p} />)}
              </div>
           </div>
        )}
        {activeTab === TABS.RECRUITING && (
          <div className="space-y-4">
             {/* Recruiting UI similar to before but with filtering logic for recruits */}
             <div className="bg-slate-800 p-4 rounded-xl flex justify-between">
                <div><h2 className="font-bold text-white">Target Board</h2></div>
                <div className="text-right font-bold text-emerald-400">{recruitingPoints} Pts</div>
             </div>
             <div className="grid grid-cols-1 gap-4">
                {getFilteredItems(recruits, recruitingFilter).map((r: any) => (
                   <div key={r.id} className="bg-slate-800 p-4 rounded-xl border border-slate-700 flex justify-between">
                      <div>
                        <div className="font-bold text-white">{r.name} <span className="text-emerald-500">{r.rating}</span></div>
                        <div className="text-xs text-slate-400">{r.position} • {r.stars} Star</div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => handleRecruitAction('SCOUT', r.id)} className="px-3 py-1 bg-indigo-600 rounded text-xs font-bold text-white">Scout</button>
                        <button onClick={() => handleRecruitAction('VISIT', r.id)} className="px-3 py-1 bg-slate-700 rounded text-xs font-bold text-white">Visit</button>
                      </div>
                   </div>
                ))}
             </div>
          </div>
        )}
        {activeTab === TABS.STRATEGY && (
          <StrategyPanel strategy={userTeam.strategy} onUpdate={(s) => setLeague(l => l.map(t => t.id === userTeamId ? { ...t, strategy: s } : t))} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ICONS, INITIAL_LEAGUE, generateBalancedRoster, calculateStars } from './constants';
import { Team, GameResult, Recruit, Position, Matchup, SeasonStage, Coach } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateRecruits } from './services/geminiService';
import { generateSeasonSchedule, simulateMatch, getStandings, generatePlayoffs } from './utils/seasonUtils';

const TABS = {
  DASHBOARD: 'Dashboard',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  STANDINGS: 'Standings',
};

// Filter Definitions
const OFFENSE_POSITIONS = [Position.QB, Position.RB, Position.WR, Position.OL];
const DEFENSE_POSITIONS = [Position.DL, Position.LB, Position.DB];

const WEEKLY_RECRUITING_POINTS = 100;

type ViewState = 'CREATE_COACH' | 'JOB_OFFERS' | 'DYNASTY_HUB';

const App = () => {
  // App Mode State
  const [viewState, setViewState] = useState<ViewState>('CREATE_COACH');
  const [seasonStage, setSeasonStage] = useState<SeasonStage>(SeasonStage.REGULAR_SEASON);
  const [coach, setCoach] = useState<Coach>({
    name: '',
    almaMater: '',
    level: 1,
    prestige: 0,
    offense: 'Balanced',
    defense: '4-3',
    history: []
  });

  // Data State
  const [league, setLeague] = useState<Team[]>(INITIAL_LEAGUE);
  const [userTeamId, setUserTeamId] = useState<string>('');
  const [jobOffers, setJobOffers] = useState<Team[]>([]);
  const [schedule, setSchedule] = useState<Matchup[]>([]);

  // UI State
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [week, setWeek] = useState(1);
  const [simResult, setSimResult] = useState<GameResult | null>(null);
  const [loading, setLoading] = useState(false);

  // Recruiting
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [scholarshipsAvailable, setScholarshipsAvailable] = useState(25);
  const [recruitingPoints, setRecruitingPoints] = useState(WEEKLY_RECRUITING_POINTS);
  const [recruitingFilter, setRecruitingFilter] = useState('All');
  const [rosterFilter, setRosterFilter] = useState('All');

  // Computed
  const userTeam = league.find(t => t.id === userTeamId);
  const weeklySchedule = schedule.filter(m => m.week === week);
  const userMatchup = weeklySchedule.find(m => m.homeTeamId === userTeamId || m.awayTeamId === userTeamId);
  const currentOpponent = userMatchup 
    ? league.find(t => t.id === (userMatchup.homeTeamId === userTeamId ? userMatchup.awayTeamId : userMatchup.homeTeamId))
    : null;

  // --- Initialization ---

  // Generate Recruits
  useEffect(() => {
    const fetchRecruits = async () => {
      const newRecruits = await generateRecruits(40);
      const formattedRecruits = newRecruits.map((r: any, idx: number) => ({
        id: `r-${idx}`,
        ...r,
        position: r.position as Position, 
        rating: Math.floor(Math.random() * 20) + 60 + (r.stars * 5),
        year: 'FR',
        stats: { games: 0, yards: 0, touchdowns: 0 },
        potential: Math.floor(Math.random() * 20) + 70,
        interest: Math.floor(Math.random() * 30) + 10,
        offers: [],
        committedTo: null,
        isScouted: false,
        isOffered: false
      }));
      setRecruits(formattedRecruits);
    };
    fetchRecruits();
  }, []);

  // --- Handlers ---

  const handleCreateCoach = () => {
    if (!coach.name || !coach.almaMater) {
       alert("Please enter your name and alma mater.");
       return;
    }

    // Generate Job Offers based on Level
    let maxPrestige = 60;
    if (coach.level === 2) maxPrestige = 70; // Coordinator
    if (coach.level === 3) maxPrestige = 75; // G5 HC
    if (coach.level === 4) maxPrestige = 85; // P4 HC
    if (coach.level === 5) maxPrestige = 100; // Legend

    const minPrestige = Math.max(0, maxPrestige - 20);

    const availableTeams = league.filter(t => t.prestige <= maxPrestige && t.prestige >= minPrestige);
    // Shuffle and pick 4
    const offers = availableTeams.sort(() => Math.random() - 0.5).slice(0, 4);

    setJobOffers(offers);
    setViewState('JOB_OFFERS');
  };

  const handleSelectJob = (teamId: string) => {
    const team = league.find(t => t.id === teamId)!;

    // Generate full roster for user team if empty (first time)
    // AI teams get generated implicitly when needed, but user team needs it now
    const updatedLeague = league.map(t => {
       if (t.id === teamId) {
          // If taking a new job, generate roster based on prestige
          return { 
            ...t, 
            roster: generateBalancedRoster(teamId, t.prestige),
            strategy: { ...t.strategy, offense: coach.offense as any, defense: coach.defense as any } 
          };
       }
       // Reset other teams for new season if this is carousel
       if (seasonStage === SeasonStage.COACHING_CAROUSEL) {
          return {
             ...t,
             wins: 0, losses: 0,
             stats: { wins: 0, losses: 0, confWins: 0, confLosses: 0, rank: 0 }
          };
       }
       return t;
    });

    setLeague(updatedLeague);
    setUserTeamId(teamId);

    // Generate Schedule for new Season
    const newSchedule = generateSeasonSchedule(updatedLeague);
    setSchedule(newSchedule);

    setCoach(prev => ({
       ...prev, 
       history: [...prev.history, `Hired by ${team.name} (${new Date().getFullYear()})`]
    }));

    setWeek(1);
    setSeasonStage(SeasonStage.REGULAR_SEASON);
    setViewState('DYNASTY_HUB');
  };

  const handleSimulateGame = async () => {
    if (loading || !userTeam || !currentOpponent) return;
    setLoading(true);

    const result = await simulateGameWithAI(userTeam, currentOpponent);

    if (result) {
      result.week = week;
      setSimResult(result);
    }
    setLoading(false);
  };

  const generateEndOfSeasonOffers = () => {
    // Logic: If user overperformed prestige wins, get better offers
    // Expected wins approx Prestige / 10
    if (!userTeam) return;

    const expectedWins = Math.round(userTeam.prestige / 10);
    const actualWins = userTeam.stats.wins;
    const diff = actualWins - expectedWins;

    let newPrestigeBase = coach.prestige + (diff * 2);
    // Bounds based on current coach level
    if (coach.level === 1) newPrestigeBase = Math.min(newPrestigeBase, 70); 

    // Find teams around this new prestige
    const targetPrestige = Math.max(40, Math.min(99, userTeam.prestige + (diff * 3)));

    const potentialOffers = league.filter(t => 
       t.id !== userTeamId && 
       t.prestige >= targetPrestige - 10 && 
       t.prestige <= targetPrestige + 10
    );

    const offers = potentialOffers.sort(() => Math.random() - 0.5).slice(0, 3);
    setJobOffers(offers);
    setSeasonStage(SeasonStage.COACHING_CAROUSEL);
  };

  const advanceWeek = () => {
    const updatedLeague = [...league];
    const updatedSchedule = schedule.map(match => {
      if (match.week !== week) return match;
      if (match.played) return match;

      let homeScore = 0, awayScore = 0, winnerId = '';

      if (match.id === userMatchup?.id && simResult) {
        // simResult was generated with (User, Opponent), so simResult.stats.homeScore is User's score
        // We need to map this to the actual match structure which might have User as Away
        const userScore = simResult.stats?.homeScore || 0;
        const oppScore = simResult.stats?.awayScore || 0;

        if (match.homeTeamId === userTeamId) {
           homeScore = userScore;
           awayScore = oppScore;
        } else {
           homeScore = oppScore;
           awayScore = userScore;
        }

        winnerId = homeScore > awayScore ? match.homeTeamId : match.awayTeamId;
      } else {
        const home = updatedLeague.find(t => t.id === match.homeTeamId)!;
        const away = updatedLeague.find(t => t.id === match.awayTeamId)!;
        const result = simulateMatch(home, away);
        homeScore = result.homeScore;
        awayScore = result.awayScore;
        winnerId = homeScore > awayScore ? match.homeTeamId : match.awayTeamId;
      }

      const homeTeam = updatedLeague.find(t => t.id === match.homeTeamId)!;
      const awayTeam = updatedLeague.find(t => t.id === match.awayTeamId)!;

      if (winnerId === match.homeTeamId) {
        homeTeam.stats.wins++;
        awayTeam.stats.losses++;
        if (match.isConferenceGame) { homeTeam.stats.confWins++; awayTeam.stats.confLosses++; }
      } else {
        awayTeam.stats.wins++;
        homeTeam.stats.losses++;
        if (match.isConferenceGame) { awayTeam.stats.confWins++; homeTeam.stats.confLosses++; }
      }

      return { ...match, played: true, homeScore, awayScore, winnerId };
    });

    setLeague(updatedLeague);
    setSchedule(updatedSchedule);
    setSimResult(null);
    setRecruitingPoints(WEEKLY_RECRUITING_POINTS);

    if (week === 12) {
       setSeasonStage(SeasonStage.POST_SEASON);
       const playoffs = generatePlayoffs(updatedLeague);
       setSchedule([...updatedSchedule, ...playoffs]);
       setWeek(14); 
    } else if (week >= 14 && seasonStage === SeasonStage.POST_SEASON) {
       // Check if more playoff games exist? Simplified for now.
       generateEndOfSeasonOffers();
    } else {
       setWeek(w => w + 1);
    }
  };

  const getFilteredItems = (items: any[], filter: string) => {
    if (filter === 'All') return items;
    if (filter === 'Offense') return items.filter((i: any) => OFFENSE_POSITIONS.includes(i.position));
    if (filter === 'Defense') return items.filter((i: any) => DEFENSE_POSITIONS.includes(i.position));
    return items.filter((i: any) => i.position === filter);
  };

  const handleRecruitAction = (action: 'SCOUT' | 'CALL' | 'VISIT' | 'OFFER', recruitId: string) => {
    const COSTS = { SCOUT: 10, CALL: 5, VISIT: 25, OFFER: 0 };
    const cost = COSTS[action];
    if (recruitingPoints < cost) return;
    if (action === 'OFFER' && scholarshipsAvailable <= 0) return;
    if (cost > 0) setRecruitingPoints(p => p - cost);
    setRecruits(prev => prev.map(r => {
      if (r.id !== recruitId) return r;
      let updates: Partial<Recruit> = {};
      let boost = 0;
      switch(action) {
        case 'SCOUT': updates.isScouted = true; boost = 2; break;
        case 'CALL': boost = Math.floor(Math.random() * 4) + 2; break;
        case 'VISIT': boost = Math.floor(Math.random() * 10) + 10; break;
        case 'OFFER': if(!r.isOffered) { updates.isOffered = true; boost = 15; } break;
      }
      return { ...r, ...updates, interest: Math.min(100, r.interest + boost) };
    }));
  };

  // --- Views ---

  if (viewState === 'CREATE_COACH') {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
         <div className="max-w-2xl w-full bg-slate-800 rounded-xl border border-slate-700 p-8 shadow-2xl">
            <h1 className="text-3xl font-black text-white mb-2 flex items-center gap-2">
              <ICONS.Users className="text-emerald-500"/> Coach Creation
            </h1>
            <p className="text-slate-400 mb-6">Build your persona. Your experience determines your starting offers.</p>

            <div className="space-y-6">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-slate-300 mb-2">Coach Name</label>
                    <input 
                      type="text" 
                      value={coach.name} 
                      onChange={e => setCoach({...coach, name: e.target.value})}
                      className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-white focus:border-emerald-500 outline-none"
                      placeholder="e.g. Nick Saban"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-300 mb-2">Alma Mater</label>
                    <input 
                      type="text" 
                      value={coach.almaMater} 
                      onChange={e => setCoach({...coach, almaMater: e.target.value})}
                      className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-white focus:border-emerald-500 outline-none"
                      placeholder="e.g. Kent State"
                    />
                  </div>
               </div>

               <div>
                 <label className="block text-sm font-bold text-slate-300 mb-2">Experience Level</label>
                 <div className="grid grid-cols-1 gap-2">
                    {[
                      { l: 1, title: 'High School Coach', desc: 'Start at the bottom. 1-2 Star offers.' },
                      { l: 2, title: 'Position Coach / Coordinator', desc: 'Mid-tier. 2-3 Star offers.' },
                      { l: 3, title: 'Group of 5 Head Coach', desc: 'Established. 3-4 Star offers.' },
                      { l: 4, title: 'Power 4 Head Coach', desc: 'Veteran. 4-5 Star offers.' },
                      { l: 5, title: 'College Legend', desc: 'Any job you want. 6 Star offers.' }
                    ].map(opt => (
                       <button
                         key={opt.l}
                         onClick={() => setCoach({...coach, level: opt.l})}
                         className={`p-3 rounded text-left border transition-all ${
                           coach.level === opt.l 
                           ? 'bg-emerald-600/20 border-emerald-500' 
                           : 'bg-slate-900 border-slate-700 hover:border-slate-500'
                         }`}
                       >
                          <div className={`font-bold ${coach.level === opt.l ? 'text-emerald-400' : 'text-white'}`}>{opt.title}</div>
                          <div className="text-xs text-slate-500">{opt.desc}</div>
                       </button>
                    ))}
                 </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-slate-300 mb-2">Offensive Playbook</label>
                    <select 
                       value={coach.offense}
                       onChange={e => setCoach({...coach, offense: e.target.value})}
                       className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-white"
                    >
                      {['Balanced', 'Spread', 'Pro-Style', 'Option', 'Air Raid', 'Run Heavy'].map(o => <option key={o} value={o}>{o}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-300 mb-2">Defensive Scheme</label>
                    <select 
                       value={coach.defense}
                       onChange={e => setCoach({...coach, defense: e.target.value})}
                       className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-white"
                    >
                      {['Balanced', '4-3', '3-4', 'Blitz Heavy', '4-2-5', '3-3-5'].map(o => <option key={o} value={o}>{o}</option>)}
                    </select>
                  </div>
               </div>

               <button 
                 onClick={handleCreateCoach}
                 className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-lg shadow-lg shadow-emerald-900/50 transition-all mt-4"
               >
                 Start Career
               </button>
            </div>
         </div>
      </div>
    )
  }

  if (viewState === 'JOB_OFFERS') {
    return (
      <div className="min-h-screen bg-slate-900 text-slate-200 p-8">
        <div className="max-w-6xl mx-auto">
          <h1 className="text-4xl font-black text-white mb-2">Job Offers</h1>
          <p className="text-slate-400 mb-8">Teams interested in your services based on your experience.</p>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
             {jobOffers.map(team => (
               <div key={team.id} className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden group hover:border-emerald-500 transition-all relative">
                 <div className={`h-2 ${team.color} w-full`}></div>
                 <div className="p-6">
                    <div className="flex justify-between items-start mb-4">
                       <div>
                          <h2 className="text-2xl font-black text-white">{team.name}</h2>
                          <div className="text-sm text-slate-400">{team.conference}</div>
                       </div>
                       <div className="flex">
                         {Array.from({length: calculateStars(team.prestige)}).map((_, i) => (
                            <svg key={i} className="w-4 h-4 text-yellow-500 fill-current" viewBox="0 0 24 24"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
                         ))}
                       </div>
                    </div>

                    <div className="space-y-2 mb-6">
                       <div className="flex justify-between text-sm">
                         <span className="text-slate-500">Prestige</span>
                         <span className="font-bold text-white">{team.prestige}</span>
                       </div>
                       <div className="flex justify-between text-sm">
                         <span className="text-slate-500">Nickname</span>
                         <span className="font-bold text-white">{team.nickname}</span>
                       </div>
                    </div>

                    <button 
                      onClick={() => handleSelectJob(team.id)}
                      className="w-full py-3 bg-slate-700 hover:bg-emerald-600 text-white font-bold rounded transition-colors flex items-center justify-center gap-2"
                    >
                       <ICONS.Briefcase className="w-4 h-4"/> Accept Job
                    </button>
                 </div>
               </div>
             ))}
          </div>
        </div>
      </div>
    );
  }

  // --- COACHING CAROUSEL (End of Season) ---
  if (seasonStage === SeasonStage.COACHING_CAROUSEL) {
     return (
        <div className="min-h-screen bg-slate-900 text-slate-200 p-8 flex flex-col items-center">
           <div className="max-w-4xl w-full">
              <h1 className="text-4xl font-black text-white mb-6 text-center">Coaching Carousel</h1>
              <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 mb-8">
                 <h2 className="text-xl font-bold text-white mb-2">Season Recap</h2>
                 <p className="text-slate-400 mb-4">You led {userTeam?.name} to a {userTeam?.stats.wins}-{userTeam?.stats.losses} record.</p>
                 <button 
                   onClick={() => handleSelectJob(userTeamId)} // Stay
                   className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded mr-4"
                 >
                   Stay at {userTeam?.name} (Extend Contract)
                 </button>
              </div>

              <h2 className="text-2xl font-bold text-white mb-4">New Opportunities</h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 {jobOffers.map(team => (
                   <div key={team.id} className="bg-slate-800 rounded-xl border border-slate-700 p-6 hover:border-yellow-500 transition-colors cursor-pointer" onClick={() => handleSelectJob(team.id)}>
                      <div className="flex justify-between mb-2">
                         <h3 className="font-bold text-lg text-white">{team.name}</h3>
                         <span className="text-yellow-400 font-bold">{calculateStars(team.prestige)} ★</span>
                      </div>
                      <p className="text-sm text-slate-400">{team.conference}</p>
                      <div className="mt-4 text-emerald-400 text-sm font-bold uppercase tracking-wide">Click to Sign</div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
     )
  }

  if (!userTeam) return null;

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className={`p-3 rounded-lg text-white shadow-lg ${userTeam.color}`}>
            <div className="font-bold text-xl">{userTeam.abbreviation}</div>
          </div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Record</div>
            <div className="text-2xl font-black text-white">{userTeam.stats.wins} - {userTeam.stats.losses}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
          <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400"><ICONS.Calendar /></div>
          <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Week</div>
            <div className="text-2xl font-black text-white">{week}</div>
          </div>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
           <div className="p-3 bg-purple-500/10 rounded-lg text-purple-400"><ICONS.Clipboard /></div>
           <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Prestige</div>
            <div className="text-2xl font-black text-white flex items-center gap-2">
               {userTeam.prestige} 
               <span className="text-sm font-normal text-yellow-500 bg-yellow-500/10 px-2 rounded flex items-center gap-1">
                  {calculateStars(userTeam.prestige)} <svg className="w-3 h-3 fill-current" viewBox="0 0 24 24"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
               </span>
            </div>
           </div>
        </div>
         <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex items-center space-x-4">
           <div className="p-3 bg-yellow-500/10 rounded-lg text-yellow-400"><ICONS.Trophy /></div>
           <div>
            <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">Rank</div>
            <div className="text-2xl font-black text-white">{userTeam.stats.rank > 0 ? `#${userTeam.stats.rank}` : 'NR'}</div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Matchup Card */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-xl border border-slate-700 overflow-hidden relative">
           <div className="p-6 border-b border-slate-700/50 flex justify-between items-center">
              <h2 className="text-lg font-bold text-white flex items-center gap-2">
                 <ICONS.Football className="w-5 h-5 text-emerald-400"/> {seasonStage === SeasonStage.POST_SEASON ? 'Post Season' : 'Next Game'}
              </h2>
              {simResult && <span className="text-xs bg-slate-700 text-slate-300 px-2 py-1 rounded">Final</span>}
           </div>

           <div className="p-8">
             {seasonStage === SeasonStage.POST_SEASON ? (
                <div className="text-center">
                   <h3 className="text-2xl font-bold text-white mb-4">Playoff Time</h3>
                   <div className="space-y-2 mb-6">
                      {schedule.filter(m => m.isPlayoff).map(m => {
                         const h = league.find(t => t.id === m.homeTeamId);
                         const a = league.find(t => t.id === m.awayTeamId);
                         return (
                            <div key={m.id} className="bg-slate-950/50 p-3 rounded flex justify-between text-sm">
                               <span className={m.winnerId === h?.id ? 'text-emerald-400 font-bold' : 'text-slate-300'}>{h?.name}</span>
                               <span className="text-slate-500">vs</span>
                               <span className={m.winnerId === a?.id ? 'text-emerald-400 font-bold' : 'text-slate-300'}>{a?.name}</span>
                            </div>
                         )
                      })}
                   </div>
                   <button onClick={advanceWeek} className="w-full py-3 bg-emerald-600 text-white font-bold rounded">Simulate Round</button>
                </div>
             ) : !currentOpponent ? (
               <div className="text-center py-12">
                 <div className="text-slate-500 mb-4">Bye Week</div>
