           <h3 className="text-slate-200 font-bold mb-4 sticky top-0 bg-slate-800 pb-2">League Scores</h3>
           <div className="space-y-2">
              {weeklySchedule.filter(m => m.played).map(m => {
                 const h = league.find(t => t.id === m.homeTeamId);
                 const a = league.find(t => t.id === m.awayTeamId);
                 if (!h || !a) return null;
                 const winner = m.homeScore! > m.awayScore! ? h : a;
                 return (
                   <div key={m.id} className="flex justify-between items-center text-sm p-2 bg-slate-700/30 rounded border border-slate-700/50">
                      <div className="flex gap-2">
                        <span className={winner === h ? 'text-emerald-400 font-bold' : 'text-slate-400'}>{h.abbreviation} {m.homeScore}</span>
                        <span className="text-slate-600">-</span>
