    const actualWins = userTeam.stats.wins;
    const diff = actualWins - expectedWins;

    let newPrestigeBase = coach.prestige + (diff * 2);
    // Bounds based on current coach level
    if (coach.level === 1) newPrestigeBase = Math.min(newPrestigeBase, 70); 

