export const generateRandomPlayer = (id: string, fixedPos?: Position, minRating = 60, maxRating = 99): any => {
  const posKeys = Object.keys(Position);
  const position = fixedPos || Position[posKeys[Math.floor(Math.random() * posKeys.length)] as keyof typeof Position];

  const yearKeys = Object.keys(PlayerYear);
  const year = PlayerYear[yearKeys[Math.floor(Math.random() * yearKeys.length)] as keyof typeof PlayerYear];

  const yearBonus = year === PlayerYear.SR ? 4 : year === PlayerYear.JR ? 2 : year === PlayerYear.SO ? 1 : 0;
  const actualRating = Math.min(99, Math.floor(Math.random() * (maxRating - minRating + 1)) + minRating + yearBonus);

  return {
    id,
    name: `${firstNames[Math.floor(Math.random() * firstNames.length)]} ${lastNames[Math.floor(Math.random() * lastNames.length)]}`,
    position,
    year,
    rating: actualRating,
    hometown: hometowns[Math.floor(Math.random() * hometowns.length)],
    stats: { games: 0, yards: 0, touchdowns: 0 },
    potential: Math.floor(Math.random() * 20) + 80
  };
};

// Calculate Star Rating based on Prestige
export const calculateStars = (prestige: number): number => {
  if (prestige >= 90) return 6;
  if (prestige >= 80) return 5;
  if (prestige >= 70) return 4;
  if (prestige >= 60) return 3;
  if (prestige >= 40) return 2;
  return 1;
};

export const generateBalancedRoster = (teamId: string, prestige: number) => {
  const distribution = {
    [Position.QB]: 4,
    [Position.RB]: 6,
    [Position.WR]: 9,
    [Position.OL]: 14,
    [Position.DL]: 10,
    [Position.LB]: 9,
    [Position.DB]: 12,
    [Position.K]: 3
  };

  let roster: any[] = [];
  let idCounter = 0;

  const stars = calculateStars(prestige);

  // Roster scaling based on Stars (Prestige)
  let baseMin = 50;
  let baseMax = 70;

  switch(stars) {
    case 6: baseMin = 82; baseMax = 99; break; // Elite
    case 5: baseMin = 78; baseMax = 92; break; // Contender
    case 4: baseMin = 74; baseMax = 88; break; // Good
    case 3: baseMin = 68; baseMax = 82; break; // Average
    case 2: baseMin = 62; baseMax = 76; break; // Rebuilding
    case 1: baseMin = 55; baseMax = 70; break; // Struggling
  }

  Object.entries(distribution).forEach(([pos, count]) => {
    for (let i = 0; i < count; i++) {
      // Top of depth chart is better
      const isStarter = i < Math.ceil(count * 0.3);
      const min = isStarter ? baseMin + 3 : baseMin - 5;
      const max = isStarter ? baseMax : baseMax - 8;

      // Random variance
      roster.push(generateRandomPlayer(`${teamId}-p-${idCounter++}`, pos as Position, min, max));
    }
  });

  return roster;
};

