  const handleRecruitAction = (action: 'SCOUT' | 'CALL' | 'VISIT' | 'OFFER', recruitId: string) => {
    const COSTS = { SCOUT: 10, CALL: 5, VISIT: 25, OFFER: 0 };
    const cost = COSTS[action];
    if (recruitingPoints < cost) return;
    if (action === 'OFFER' && scholarshipsAvailable <= 0) return;
    if (cost > 0) setRecruitingPoints(p => p - cost);
    setRecruits(prev => prev.map(r => {
      if (r.id !== recruitId) return r;
      let updates: Partial<Recruit> = { isTargeted: true }; // Always add to target board
      let boost = 0;
      switch(action) {
        case 'SCOUT': updates.isScouted = true; boost = 2; break;
        case 'CALL': boost = Math.floor(Math.random() * 4) + 2; break;
        case 'VISIT': boost = Math.floor(Math.random() * 10) + 10; break;
        case 'OFFER': if(!r.isOffered) { updates.isOffered = true; boost = 15; } break;
      }
      return { ...r, ...updates, interest: Math.min(100, r.interest + boost) };
    }));
  };

  const movePlayerInRoster = (playerIndex: number, direction: 'up' | 'down') => {
      if (!userTeam) return;

      const newRoster = [...userTeam.roster];
      const targetIndex = direction === 'up' ? playerIndex - 1 : playerIndex + 1;

      // Swap logic:
      // Note: This swaps in the master list. 
      // Depth charts are usually subsets (Positions). 
      // We need to swap them in a way that respects the visual order within the position group.

      // 1. Get the player at current index
      const player = newRoster[playerIndex];
      // 2. Find the player in the same position that is visually above/below
      //    We need to scan the array to find the adjacent player of the SAME position.

      let swapIndex = -1;
      if (direction === 'up') {
          for (let i = playerIndex - 1; i >= 0; i--) {
              if (newRoster[i].position === player.position) {
                  swapIndex = i;
                  break;
              }
          }
      } else {
          for (let i = playerIndex + 1; i < newRoster.length; i++) {
            if (newRoster[i].position === player.position) {
                swapIndex = i;
                break;
            }
        }
      }

      if (swapIndex !== -1) {
          // Perform swap
          [newRoster[playerIndex], newRoster[swapIndex]] = [newRoster[swapIndex], newRoster[playerIndex]];

          setLeague(prev => prev.map(t => t.id === userTeamId ? { ...t, roster: newRoster } : t));
      }
  };

