  const handleSwapOpponent = (targetTeamId: string) => {
    const newSchedule = [...schedule];
    const userMatchIdx = newSchedule.findIndex(m => m.week === 1 && (m.homeTeamId === userTeamId || m.awayTeamId === userTeamId));
    const targetMatchIdx = newSchedule.findIndex(m => m.week === 1 && (m.homeTeamId === targetTeamId || m.awayTeamId === targetTeamId));

    if (userMatchIdx === -1 || targetMatchIdx === -1 || userMatchIdx === targetMatchIdx) return;

    const userMatch = newSchedule[userMatchIdx];
    const targetMatch = newSchedule[targetMatchIdx];

    const userOpponentId = userMatch.homeTeamId === userTeamId ? userMatch.awayTeamId : userMatch.homeTeamId;
    const userOpponent = league.find(t => t.id === userOpponentId);
    const targetOpponentId = targetMatch.homeTeamId === targetTeamId ? targetMatch.awayTeamId : targetMatch.homeTeamId;

    // Swap Logic: Bring Target to User Match
    if (userMatch.homeTeamId === userTeamId) userMatch.awayTeamId = targetTeamId;
    else userMatch.homeTeamId = targetTeamId;

    // Put User's Old Opponent in Target's old slot
    if (targetMatch.homeTeamId === targetTeamId) targetMatch.homeTeamId = userOpponentId;
    else targetMatch.awayTeamId = userOpponentId;

    // Update Conference Game flags
