// Helper to shuffle array
const shuffle = <T>(array: T[]): T[] => {
    let currentIndex = array.length,  randomIndex;
    while (currentIndex != 0) {
      randomIndex = Math.floor(Math.random() * currentIndex);
      currentIndex--;
      [array[currentIndex], array[randomIndex]] = [
        array[randomIndex], array[currentIndex]];
    }
    return array;
};

export const generateSeasonSchedule = (teams: Team[]): Matchup[] => {
  const schedule: Matchup[] = [];
  const teamsByConf: Record<string, Team[]> = {};

  // Group teams
  teams.forEach(t => {
    if (!teamsByConf[t.conference]) teamsByConf[t.conference] = [];
    teamsByConf[t.conference].push(t);
  });

  const CONFERENCE_WEEKS = [4, 5, 6, 7, 8, 9, 10, 11, 12];
  const NON_CONF_WEEKS = [1, 2, 3];

  // 1. Generate Conference Games (Weeks 4-12)
  // For each conference, generate pairings for these weeks.
  Object.entries(teamsByConf).forEach(([confName, confTeams]) => {
      if (confName === 'Independent') return; // Handle later

      // Simple rotation for intra-conference
      // If we have N teams, we can generate pairings.
      // To ensure randomness but coverage, we'll just shuffle and pair up each week.

      CONFERENCE_WEEKS.forEach(week => {
          const available = shuffle([...confTeams]);
          while (available.length >= 2) {
              const home = available.pop()!;
              const away = available.pop()!;

              schedule.push({
                id: `w${week}-${home.id}-${away.id}`,
                week,
                homeTeamId: home.id,
                awayTeamId: away.id,
                played: false,
                isUserGame: false,
                isConferenceGame: true,
                isPlayoff: false
              });
          }
          // If odd number, one team left over. They need a game.
          // In a real scheduler this is complex. Here, we'll pair them with an Independent or a team from another odd conference.
          // For simplicity in this logic, we assume even conferences or we leave them with a bye (not ideal).
          // To fix "odd number" issues simply: We will add a "Bye" if needed or pair with Indep.
          if (available.length > 0) {
               // Stash for cleanup? Or just ignore for now (Bye week).
               // Let's pair with Independent to fill gaps.
          }
      });
  });

  // 2. Generate Non-Conference Games (Weeks 1-3)
  // Global shuffle of ALL teams
  NON_CONF_WEEKS.forEach(week => {
      const available = shuffle([...teams]);
      while (available.length >= 2) {
          const home = available.pop()!;
          const away = available.pop()!;

          schedule.push({
            id: `w${week}-${home.id}-${away.id}`,
            week,
            homeTeamId: home.id,
            awayTeamId: away.id,
            played: false,
            isUserGame: false,
            isConferenceGame: home.conference === away.conference,
            isPlayoff: false
          });
      }
  });

  // 3. Handle Independents for Weeks 4-12
  // They were excluded from step 1. They need games in weeks 4-12.
  // In Step 1, we only paired Conf teams. Independents are free.
  // Pair Independents with each other or random leftover conf teams (if odd).
  // Since we assumed even conferences for simplicity, Independents play each other.
  // If odd number of Independents, someone gets a bye.
  const independents = teamsByConf['Independent'] || [];

  if (independents.length > 0) {
      CONFERENCE_WEEKS.forEach(week => {
          const available = shuffle([...independents]);
          while (available.length >= 2) {
              const home = available.pop()!;
              const away = available.pop()!;
              schedule.push({
                  id: `w${week}-${home.id}-${away.id}`,
                  week,
                  homeTeamId: home.id,
                  awayTeamId: away.id,
                  played: false,
                  isUserGame: false,
                  isConferenceGame: false,
                  isPlayoff: false
              });
          }
      });
  }

  // NOTE: This basic generator assumes even numbers for simplicity. 
  // In a robust app, we'd use a round-robin polygon method.

  return schedule;
};

export const simulateMatch = (home: Team, away: Team): { homeScore: number, awayScore: number } => {
  // Simple ELO-like simulation based on Prestige
  const prestigeDiff = home.prestige - away.prestige;
  const homeAdvantage = 3; // Home field worth ~3 points of prestige

  const winProbability = 0.5 + ((prestigeDiff + homeAdvantage) / 100);

  // Randomized outcome
  const rand = Math.random();
  const homeWin = rand < winProbability;

  // Score generation
  const baseScore = 24;
  const variance = Math.floor(Math.random() * 21) - 10; // -10 to +10

  let homeScore = baseScore + variance + (prestigeDiff / 2);
  let awayScore = baseScore + variance - (prestigeDiff / 2);

  if (homeWin && homeScore <= awayScore) {
      homeScore = awayScore + 3;
  } else if (!homeWin && awayScore <= homeScore) {
      awayScore = homeScore + 3;
  }

  return {
    homeScore: Math.max(0, Math.floor(homeScore)),
    awayScore: Math.max(0, Math.floor(awayScore))
  };
};

export const getStandings = (teams: Team[]): Team[] => {
  return [...teams].sort((a, b) => {
    // Sort by Wins, then Prestige (tiebreaker)
    if (a.stats.wins !== b.stats.wins) return b.stats.wins - a.stats.wins;
    return b.prestige - a.prestige;
  });
};

export const getAPTop25 = (teams: Team[]): Team[] => {
    // AP Logic: Wins, then PD, then Prestige
    return [...teams].sort((a, b) => {
        if (a.stats.wins !== b.stats.wins) return b.stats.wins - a.stats.wins;
        if (a.stats.losses !== b.stats.losses) return a.stats.losses - b.stats.losses;
        const pdA = a.stats.pointsFor - a.stats.pointsAgainst;
        const pdB = b.stats.pointsFor - b.stats.pointsAgainst;
        if (pdA !== pdB) return pdB - pdA;
        return b.prestige - a.prestige;
    }).slice(0, 25);
}

export const getCoachesTop25 = (teams: Team[]): Team[] => {
    // Coaches Logic: Wins, then Prestige (Bias), then PD
    return [...teams].sort((a, b) => {
        if (a.stats.wins !== b.stats.wins) return b.stats.wins - a.stats.wins;
        if (a.stats.losses !== b.stats.losses) return a.stats.losses - b.stats.losses;
        // Heavy prestige weight for coaches poll bias
        if (b.prestige !== a.prestige) return b.prestige - a.prestige;
        const pdA = a.stats.pointsFor - a.stats.pointsAgainst;
        const pdB = b.stats.pointsFor - b.stats.pointsAgainst;
        return pdB - pdA;
    }).slice(0, 25);
}

export const getCFPTop25 = (teams: Team[]): Team[] => {
    // CFP Logic: Quality check. Combination of Record + Prestige + PD
    // Score = (Wins * 100) - (Losses * 120) + (Prestige) + (PD * 0.2)
    return [...teams].sort((a, b) => {
        const scoreA = (a.stats.wins * 100) - (a.stats.losses * 120) + (a.prestige) + ((a.stats.pointsFor - a.stats.pointsAgainst) * 0.2);
        const scoreB = (b.stats.wins * 100) - (b.stats.losses * 120) + (b.prestige) + ((b.stats.pointsFor - b.stats.pointsAgainst) * 0.2);
        return scoreB - scoreA;
    }).slice(0, 25);
}

export const generatePlayoffs = (teams: Team[]): Matchup[] => {
  // Top 12 Teams
  const ranked = getCFPTop25(teams).slice(0, 12);
  const matchups: Matchup[] = [];

  // Round 1: 5-12, 6-11, 7-10, 8-9 (Top 4 Byes - simulated by omitting for now or adding R2 later)
  matchups.push({
    id: 'playoff-1', week: 14, homeTeamId: ranked[4].id, awayTeamId: ranked[11].id, played: false, isUserGame: false, isConferenceGame: false, isPlayoff: true, label: 'CFP Round 1'
  });
  matchups.push({
