  });
  matchups.push({
    id: 'playoff-3', week: 14, homeTeamId: ranked[6].id, awayTeamId: ranked[9].id, played: false, isUserGame: false, isConferenceGame: false, isPlayoff: true, label: 'CFP Round 1'
  });
  matchups.push({
