// Helper: Calculate realistic interest based on team prestige vs recruit stars
const calculateRecruitInterest = (recruit: Recruit, teamPrestige: number): number => {
  let base = Math.floor(Math.random() * 10) + 1; // 1-10 random variance

  // Prestige Base: Higher prestige = higher baseline interest generally
  // 0 Prestige -> +0
  // 100 Prestige -> +30
  const prestigeBase = (teamPrestige / 100) * 30;

  // Alignment: Does the recruit "fit" this level of program?
  let alignmentMod = 0;
  const { stars } = recruit;

  if (stars === 5) {
      // 5 Stars: Elite. Only want the best.
      if (teamPrestige >= 90) alignmentMod = 40; // Loves Blue Bloods
      else if (teamPrestige >= 80) alignmentMod = 20; // Likes Contenders
      else if (teamPrestige >= 60) alignmentMod = -20; // Dislikes Average
      else alignmentMod = -60; // Hates Low Prestige
  } 
  else if (stars === 4) {
      // 4 Stars: Great talent. Want good schools.
      if (teamPrestige >= 80) alignmentMod = 25;
      else if (teamPrestige >= 60) alignmentMod = 10;
      else if (teamPrestige >= 40) alignmentMod = -10;
      else alignmentMod = -40;
  }
  else if (stars === 3) {
      // 3 Stars: Core players. Open to most, prefer decent programs.
      if (teamPrestige >= 60) alignmentMod = 15;
      else if (teamPrestige >= 40) alignmentMod = 20; // Good fit
      else alignmentMod = 0;
  }
  else {
      // 1-2 Stars: Developmental. 
      // They have high interest in lower prestige schools because it's a realistic landing spot.
      if (teamPrestige < 50) alignmentMod = 35; // "I can play here!"
      else alignmentMod = 10; // Still like big schools, but big schools don't usually offer them
  }

  // Transfer Portal Logic
  if (recruit.recruitType === 'TRANSFER') {
      // Transfers prioritize winning (Prestige) slightly more
      if (teamPrestige > 75) alignmentMod += 10;
  }

  let total = base + prestigeBase + alignmentMod;

  // Clamp between 5 and 90 (leaving room for recruiting actions to boost to 100)
  return Math.max(5, Math.min(90, Math.floor(total)));
};

