         {['SEC', 'Big Ten', 'ACC', 'Big 12', 'AAC', 'Mountain West', 'Sun Belt', 'MAC', 'CUSA', 'Independent'].map(conf => (
           <div key={conf} className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
              <div className="bg-slate-700 px-4 py-3 font-bold text-white border-b border-slate-600">{conf}</div>
              <div className="p-2">
                 <table className="w-full text-sm">
                   <thead>
                     <tr className="text-slate-500 text-xs uppercase text-left">
                       <th className="p-2">Team</th>
                       <th className="p-2 text-center">Conf</th>
                       <th className="p-2 text-center">Ovr</th>
                     </tr>
                   </thead>
                   <tbody>
                     {getStandings(league.filter(t => t.conference === conf)).map((t, i) => (
                       <tr key={t.id} className={`border-b border-slate-700/50 last:border-0 ${t.id === userTeamId ? 'bg-emerald-500/10' : ''}`}>
                         <td className="p-2 font-medium text-slate-200 flex items-center gap-2">
                           {i < 2 && <div className="w-1 h-4 bg-emerald-500 rounded-full"></div>}
                           {t.name}
                         </td>
                         <td className="p-2 text-center text-slate-400">{t.stats.confWins}-{t.stats.confLosses}</td>
                         <td className="p-2 text-center font-bold text-white">{t.stats.wins}-{t.stats.losses}</td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
              </div>
           </div>
         ))}
       </div>
    </div>
  );

  const renderRankings = () => {
    const apPoll = getAPTop25(league);
    const coachesPoll = getCoachesTop25(league);
    const cfpPoll = week >= 8 ? getCFPTop25(league) : null;

    const RankingList = ({ title, teams }: { title: string, teams: Team[] }) => (
      <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden h-full">
         <div className="bg-slate-700 px-4 py-3 font-bold text-white border-b border-slate-600 flex justify-between items-center">
            <span>{title}</span>
            <span className="text-xs font-normal text-slate-400 bg-slate-800 px-2 py-1 rounded">Week {week}</span>
         </div>
         <div className="p-0">
            <table className="w-full text-sm">
              <thead className="bg-slate-750">
                <tr className="text-slate-500 text-xs uppercase text-left">
                  <th className="p-3 w-8">#</th>
                  <th className="p-3">Team</th>
                  <th className="p-3 text-center">Rec</th>
                </tr>
              </thead>
              <tbody>
                {teams.map((t, i) => (
                  <tr key={t.id} className={`border-b border-slate-700/50 last:border-0 hover:bg-slate-700/50 transition-colors ${t.id === userTeamId ? 'bg-emerald-500/10' : ''}`}>
                    <td className="p-3 font-bold text-slate-400">{i + 1}</td>
                    <td className="p-3 font-medium text-slate-200 flex items-center gap-2">
                      <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold text-white ${t.color}`}>
                         {t.abbreviation}
                      </div>
                      {t.name}
                    </td>
                    <td className="p-3 text-center font-bold text-white">{t.stats.wins}-{t.stats.losses}</td>
                  </tr>
                ))}
              </tbody>
            </table>
         </div>
      </div>
    );

    return (
       <div className="space-y-6 animate-fade-in">
          <div className={`grid grid-cols-1 ${cfpPoll ? 'lg:grid-cols-3' : 'lg:grid-cols-2'} gap-6`}>
             <RankingList title="AP Poll" teams={apPoll} />
             <RankingList title="Coaches Poll" teams={coachesPoll} />
             {cfpPoll && <RankingList title="CFP Rankings" teams={cfpPoll} />}
          </div>
       </div>
    );
  };

  const renderRoster = () => {
    // Group by position
    // We rely on the order in the array for the depth chart
    const groups: Partial<Record<Position, any[]>> = {};
    const positions = Object.values(Position);

    // Initialize groups
    positions.forEach(p => groups[p] = []);

    // Fill groups with players
    userTeam?.roster.forEach((p) => {
        if (!groups[p.position]) groups[p.position] = [];
        groups[p.position]?.push(p);
    });

    return (
        <div className="space-y-6 animate-fade-in">
            {positions.map(pos => {
                const players = groups[pos] || [];
                if (players.length === 0) return null;

                return (
                    <div key={pos} className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
                        <div className="bg-slate-700 px-4 py-2 font-bold text-white flex justify-between items-center">
                            <span>{pos} Depth Chart</span>
                            <span className="text-xs text-slate-400 font-normal">{players.length} Players</span>
                        </div>
                        <div className="divide-y divide-slate-700/50">
                            {players.map((p, idx) => (
                                <div 
                                    key={p.id} 
                                    className={`p-3 flex items-center justify-between transition-colors cursor-move ${draggedPlayerId === p.id ? 'bg-emerald-900/40 opacity-50' : 'hover:bg-slate-700/30'}`}
                                    draggable
                                    onDragStart={(e) => handleDragStart(e, p.id)}
                                    onDragOver={handleDragOver}
                                    onDrop={(e) => handleDrop(e, p.id)}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="w-6 text-center font-bold text-slate-500">{idx + 1}</div>
                                        <div>
                                            <div className="font-bold text-white flex items-center gap-2">
                                                {p.name}
                                                {idx === 0 && <span className="text-[10px] bg-emerald-500/20 text-emerald-400 px-1.5 py-0.5 rounded uppercase font-bold">Starter</span>}
                                            </div>
                                            <div className="text-xs text-slate-400">{p.year} • {p.hometown}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="text-right mr-4">
                                            <div className="text-xl font-bold text-white">{p.rating}</div>
                                            <div className="text-[10px] text-slate-500 uppercase">OVR</div>
                                            {p.leavingStatus && <span className="text-[9px] bg-red-600 text-white px-1 rounded block text-center">LEAVING</span>}
                                        </div>
                                        <ICONS.List className="w-4 h-4 text-slate-600" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                );
            })}
        </div>
    );
  };

  const renderRecruiting = () => {
      const targets = recruits.filter(r => r.isTargeted);
      const searchPool = recruits.filter(r => !r.isTargeted);

      const RecruitRow = ({ r, showActions = true }: { r: Recruit, showActions?: boolean }) => {
        const isCommittedToUser = r.committedTo === userTeamId;
        const isCommittedToOther = r.committedTo && !isCommittedToUser;
        const committedTeamName = isCommittedToOther ? league.find(t => t.id === r.committedTo)?.name : null;
        const isTransfer = r.recruitType === 'TRANSFER';

        return (
         <div className={`p-4 rounded-xl border flex flex-col sm:flex-row justify-between gap-4 transition-all ${
             isCommittedToUser ? 'bg-emerald-900/20 border-emerald-500/50' : 
             isCommittedToOther ? 'bg-slate-800 border-red-900/30 opacity-60' : 
             'bg-slate-800 border-slate-700 hover:border-slate-600'
         }`}>
            <div className="flex gap-4">
                <div className={`flex flex-col items-center justify-center w-12 h-12 rounded-lg font-bold border ${isTransfer ? 'bg-purple-900/20 border-purple-500/50 text-purple-400' : 'bg-slate-700 border-transparent text-yellow-400'}`}>
                    {isTransfer ? 'TR' : `${r.stars}★`}
                </div>
                <div>
                  <div className="font-bold text-white text-lg flex items-center gap-2">
                      {r.name} 
                      {isCommittedToUser ? (
                          <span className="text-sm px-2 py-0.5 rounded bg-emerald-500 text-white font-black">COMMITTED</span>
                      ) : isCommittedToOther ? (
                          <span className="text-sm px-2 py-0.5 rounded bg-red-600 text-white font-bold">SIGNED: {committedTeamName}</span>
                      ) : (
                          <span className={`text-sm px-2 py-0.5 rounded ${r.interest >= 80 ? 'bg-emerald-500/20 text-emerald-400' : r.interest >= 50 ? 'bg-yellow-500/20 text-yellow-400' : 'bg-slate-600 text-slate-400'}`}>
                              {r.interest}% Int
                          </span>
                      )}
                  </div>
                  <div className="text-sm text-slate-400 flex items-center gap-2">
                    <span>{r.position}</span>
                    <span className="text-slate-600">•</span>
                    <span>{r.year}</span>
                    <span className="text-slate-600">•</span>
                    <span>{r.hometown}</span>
                  </div>
                  {r.isScouted && <div className="mt-1 text-xs text-indigo-300 italic">"{r.scoutingReport || "Scouts praise his athleticism."}"</div>}
                  <div className="mt-1 flex gap-2">
                     {r.isOffered && !r.committedTo && <span className="text-[10px] bg-emerald-600 text-white px-2 py-0.5 rounded-full font-bold">OFFERED</span>}
                     {r.isScouted && <span className="text-[10px] bg-indigo-600 text-white px-2 py-0.5 rounded-full font-bold">SCOUTED</span>}
                     {isTransfer && <span className="text-[10px] bg-purple-600 text-white px-2 py-0.5 rounded-full font-bold">PORTAL</span>}
                  </div>
                </div>
            </div>
            {showActions && !r.committedTo && (
                <div className="flex flex-wrap sm:flex-nowrap gap-2 items-center">
                  <button onClick={() => handleRecruitAction('SCOUT', r.id)} disabled={r.isScouted} className="px-3 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-700 disabled:opacity-50 rounded text-xs font-bold text-white min-w-[70px]">Scout (10)</button>
                  <button onClick={() => handleRecruitAction('CALL', r.id)} className="px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white min-w-[70px]">Call (5)</button>
                  <button onClick={() => handleRecruitAction('VISIT', r.id)} className="px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white min-w-[70px]">Visit (25)</button>
                  {r.isOffered ? (
                       <button onClick={() => handleRecruitAction('RESCIND', r.id)} className="px-3 py-2 bg-red-600 hover:bg-red-500 rounded text-xs font-bold text-white min-w-[70px]">Rescind</button>
                  ) : (
                       <button onClick={() => handleRecruitAction('OFFER', r.id)} className="px-3 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-700 disabled:opacity-50 rounded text-xs font-bold text-white min-w-[70px]">Offer</button>
                  )}
                </div>
            )}
         </div>
      )};

      // Filtering logic
      let filteredByView = searchPool;
      if (seasonStage === SeasonStage.TRANSFER_PORTAL) {
          filteredByView = searchPool.filter(r => r.recruitType === 'TRANSFER');
      } else {
          filteredByView = searchPool.filter(r => r.recruitType === 'HS');
      }

      const filteredByPos = getFilteredItems(filteredByView, recruitingFilter);
      const sortedRecruits = filteredByPos.sort((a,b) => {
          if (sortOrder === 'RANK') {
              if (a.stars !== b.stars) return b.stars - a.stars;
              return b.rating - a.rating;
          } else {
              if (a.interest !== b.interest) return b.interest - a.interest;
              return b.stars - a.stars;
          }
      });

      return (
          <div className="space-y-8 animate-fade-in">
             <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h2 className="text-2xl font-black text-white">
                        {seasonStage === SeasonStage.TRANSFER_PORTAL ? 'Transfer Portal' : 'High School Recruiting'}
                    </h2>
                    <p className="text-slate-400">
                        {seasonStage === SeasonStage.TRANSFER_PORTAL ? 'Fill immediate gaps with experienced players.' : 'Build for the future with high school talent.'}
                    </p>
                </div>
                <div className="flex items-center gap-6">
                    <div className="flex flex-col items-end">
                        <div className="text-3xl font-black text-white">{scholarshipsAvailable}</div>
                        <div className="text-xs text-slate-500">Scholarships</div>
                    </div>
                    <div className="flex flex-col items-end">
                        <div className="text-3xl font-black text-emerald-400">{recruitingPoints} <span className="text-sm font-normal text-slate-400">PTS</span></div>
                        <div className="text-xs text-slate-500">Weekly Budget</div>
                    </div>
                </div>
             </div>

             {/* Target Board */}
             <div className="space-y-4">
                 <h3 className="text-xl font-bold text-white flex items-center gap-2">
                     <ICONS.Clipboard className="text-emerald-500"/> Target Board 
                     <span className="text-sm font-normal text-slate-500">({targets.length})</span>
                 </h3>
                 {targets.length === 0 ? (
                     <div className="p-8 border-2 border-dashed border-slate-700 rounded-xl text-center text-slate-500">
                         No active targets. Scout players in the Search to add them here.
                     </div>
                 ) : (
                     <div className="grid grid-cols-1 gap-4">
                         {targets.sort((a,b) => {
                             // Committed first, then by interest
                             if (a.committedTo === userTeamId && b.committedTo !== userTeamId) return -1;
                             if (b.committedTo === userTeamId && a.committedTo !== userTeamId) return 1;
                             return b.interest - a.interest
                         }).map(r => <RecruitRow key={r.id} r={r} />)}
                     </div>
                 )}
             </div>

             <div className="border-t border-slate-800 my-4"></div>

             {/* National Search */}
             <div className="space-y-4">
                <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                        <ICONS.Search className="text-slate-500"/> {seasonStage === SeasonStage.TRANSFER_PORTAL ? 'Available Transfers' : 'High School Prospects'}
                    </h3>

                    <div className="flex flex-col sm:flex-row gap-4 w-full xl:w-auto">

                        {/* Sort Toggle */}
                        <div className="bg-slate-800 p-1 rounded-lg border border-slate-700 flex">
                            <span className="px-3 py-1.5 text-xs text-slate-500 font-bold border-r border-slate-700 mr-1 flex items-center">Sort By:</span>
                            <button onClick={() => setSortOrder('RANK')} className={`px-3 py-1.5 rounded text-xs font-bold transition-all ${sortOrder === 'RANK' ? 'bg-slate-600 text-white' : 'text-slate-400 hover:text-white'}`}>Rank</button>
                            <button onClick={() => setSortOrder('INTEREST')} className={`px-3 py-1.5 rounded text-xs font-bold transition-all ${sortOrder === 'INTEREST' ? 'bg-slate-600 text-white' : 'text-slate-400 hover:text-white'}`}>Interest</button>
                        </div>

                        {/* Pos Filter */}
                        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2 sm:pb-0">
                            {filters.map(f => (
                            <button
                                key={f}
                                onClick={() => setRecruitingFilter(f)}
                                className={`px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap transition-colors border ${
                                recruitingFilter === f 
                                ? 'bg-emerald-600/20 text-emerald-400 border-emerald-500/50' 
                                : 'bg-slate-800 text-slate-400 border-slate-700 hover:bg-slate-700'
                                }`}
                            >
                                {f}
                            </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 gap-4">
                    {sortedRecruits.length === 0 ? (
                         <div className="p-12 text-center text-slate-500 italic bg-slate-800/50 rounded-xl border border-dashed border-slate-700">
                             No players found matching this criteria.
                         </div>
                    ) : (
                        sortedRecruits.map((r: any) => (
                           <RecruitRow key={r.id} r={r} showActions={true} />
                        ))
                    )}
                </div>
             </div>
          </div>
      );
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 font-sans selection:bg-emerald-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-md bg-opacity-80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-emerald-600 rounded flex items-center justify-center">
                 <ICONS.Football className="text-white w-5 h-5" />
              </div>
              <span className="font-black text-xl tracking-tight text-white hidden sm:block">GRIDIRON<span className="text-emerald-500">AI</span></span>
            </div>
            {viewState === 'DYNASTY_HUB' && (
              <nav className="flex gap-1 md:gap-4 overflow-x-auto">
                {Object.values(TABS).map((tab) => {
                    // Hide recruiting tab during retention, logic handled elsewhere usually but safe here
                    if (seasonStage === SeasonStage.RETENTION && tab === TABS.RECRUITING) return null;
                    return (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={`px-3 py-2 text-sm font-medium rounded-md transition-colors whitespace-nowrap ${
                            activeTab === tab 
                            ? 'bg-slate-800 text-emerald-400' 
                            : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
                            }`}
                        >
                            {tab}
                        </button>
                    );
                })}
              </nav>
            )}
            {viewState !== 'DYNASTY_HUB' && (
               <div className="text-sm font-bold text-slate-500 uppercase tracking-widest">{viewState === 'CREATE_COACH' ? 'New Career' : 'Contract Offer'}</div>
            )}
          </div>
        </div>
      </header>
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === TABS.DASHBOARD && renderDashboard()}
        {activeTab === TABS.SCHEDULE && renderScheduleTab()}
        {activeTab === TABS.STANDINGS && renderStandings()}
        {activeTab === TABS.RANKINGS && renderRankings()}
        {activeTab === TABS.ROSTER && renderRoster()}
        {activeTab === TABS.RECRUITING && renderRecruiting()}
        {activeTab === TABS.STRATEGY && (
          <StrategyPanel strategy={userTeam.strategy} onUpdate={(s) => setLeague(l => l.map(t => t.id === userTeamId ? { ...t, strategy: s } : t))} />
        )}
      </main>
    </div>
  );
};

export default App;

export enum Position {
  QB = 'QB',
  RB = 'RB',
  WR = 'WR',
  OL = 'OL',
  DL = 'DL',
  LB = 'LB',
  DB = 'DB',
  K = 'K'
}

export enum PlayerYear {
  FR = 'FR',
  SO = 'SO',
  JR = 'JR',
  SR = 'SR'
}

export type Conference = 
  | 'SEC' | 'Big Ten' | 'ACC' | 'Big 12' | 'Pac-12'
  | 'AAC' | 'Mountain West' | 'Sun Belt' | 'MAC' | 'CUSA' 
  | 'Independent';

export enum SeasonStage {
  REGULAR_SEASON = 'REGULAR_SEASON',
  CONFERENCE_CHAMPIONSHIP = 'CONFERENCE_CHAMPIONSHIP',
  POST_SEASON = 'POST_SEASON',
  COACHING_CAROUSEL = 'COACHING_CAROUSEL',
  RETENTION = 'RETENTION',
  TRANSFER_PORTAL = 'TRANSFER_PORTAL',
  OFF_SEASON = 'OFF_SEASON'
}

export interface Coach {
  name: string;
  almaMater: string;
  level: number; // 1 (HS) to 5 (Legend)
  prestige: number; // Dynamic reputation
  offense: string;
  defense: string;
  history: string[]; // Career history
}

export interface Player {
  id: string;
  name: string;
  position: Position;
  year: PlayerYear;
  rating: number; // 0-100
  hometown: string;
  stats: {
    games: number;
    yards: number;
    touchdowns: number;
  };
  potential: number; // Hidden stat for development
  leavingStatus?: 'GRADUATING' | 'NFL' | 'TRANSFER' | null;
}

export interface Recruit extends Player {
  interest: number; // 0-100 (User's interest)
  topSchools: { teamId: string; interest: number }[]; // Top 5 schools
  offers: string[]; // List of other teams offering
  committedTo: string | null;
  stars: number; // 1-5
  scoutingReport?: string;
  isScouted: boolean;
  isOffered: boolean;
  isTargeted: boolean;
  recruitType: 'HS' | 'TRANSFER';
}

export interface Team {
  id: string;
  name: string;
  nickname: string;
  abbreviation: string;
  color: string;
  prestige: number; // 0-100
  stars: number; // 1-6
  conference: Conference;
  stats: {
    wins: number;
    losses: number;
    confWins: number;
    confLosses: number;
    pointsFor: number;
    pointsAgainst: number;
    rank: number; // 0 for unranked
  };
  roster: Player[];
  strategy: {
    offense: 'Balanced' | 'Spread' | 'Pro-Style' | 'Option' | 'Air Raid' | 'Run Heavy';
    defense: 'Balanced' | '4-3' | '3-4' | 'Blitz Heavy' | '4-2-5' | '3-3-5';
    aggression: number; // 1-10
  };
}

export interface GameStats {
  homeScore: number;
  awayScore: number;
  quarters: number[]; // Array of 4 numbers
  passingYards: number;
  rushingYards: number;
  turnovers: number;
  possessionTime: string;
}

export interface GameResult {
  week: number;
  opponentId: string;
  isHome: boolean;
  result: 'W' | 'L' | null;
  stats: GameStats | null;
  summary: string;
  playByPlayHighlights: string[];
}

export interface Matchup {
  id: string;
  week: number;
  homeTeamId: string;
  awayTeamId: string;
  played: boolean;
  winnerId?: string;
  homeScore?: number;
  awayScore?: number;
  isUserGame: boolean;
  isConferenceGame: boolean;
  isPlayoff?: boolean;
  label?: string; // e.g. "Peach Bowl"
}

import React from 'react';
import { Team, Position, PlayerYear, Conference } from './types';

export const ICONS = {
  Football: (props: React.SVGProps<SVGSVGElement>) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}><path d="M2 17 17 2"/><path d="m2 6 4-4"/><path d="m6 2 4 4"/><path d="m10 6 4-4"/><path d="m14 2 4 4"/><path d="m18 6 4-4"/><path d="m6 22 4-4"/><path d="m10 18 4 4"/><path d="m14 22 4-4"/><path d="m18 18 4 4"/><path d="m18 22 4-4"/></svg>
  ),
  Users: (props: React.SVGProps<SVGSVGElement>) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
